@media(max-width:700px){#enhancedHome .kvP-in .kvP-lhead{display:block!important;padding-bottom:9px!important}#enhancedHome .kvP-in .kvP-lhead>b{font-size:8px!important;letter-spacing:.16em!important;display:block;margin:0 0 7px}#enhancedHome .kvP-in .kvP-lhead .kvP-caveat{display:block;max-width:100%;margin:0;font-size:17px!important}#enhancedHome .kvP-in .kvP-lrow i{display:none}#enhancedHome .kvP-in .kvP-lrow{display:block!important;padding:7px 0}#enhancedHome .kvP-in .kvP-lrow span{font-size:10px}#enhancedHome .kvP-in .kvP-lrow b{display:block;font-size:15px!important;margin-top:4px}#enhancedHome .kvP-swrow{display:block;font-size:10px!important;padding:8px 0!important}#enhancedHome .kvP-swrow>.kvP-sw{display:flex!important;justify-content:space-between;align-items:center;width:100%!important;gap:7px;margin-top:6px}#enhancedHome .kvP-swrow>.kvP-sw i{flex:0 0 35px;width:35px!important;height:20px!important}#enhancedHome .kvP-swrow>.kvP-sw i::before{width:14px!important;height:14px!important;top:3px!important}#enhancedHome .kvP-swrow>.kvP-sw.on i::before{left:17px!important}}
@media(max-width:700px){#enhancedHome .kvP-contact #kvPtype{font-size:16px!important;line-height:1.5!important}#enhancedHome .kvP-contact #statusChip{display:block!important;width:100%;max-width:100%;border-radius:14px;letter-spacing:0;font-size:9px!important;line-height:1.5;padding:10px!important}#enhancedHome .kvP-contact #clock{display:block;font-size:9px!important;line-height:1.5;letter-spacing:0}}


/* News sections 02/03: photos are nested in .kn-tart, not direct children of .kn-tile.
 Contain the entire approved photograph: do not crop identifying landmarks. */
#enhancedHome .kn-tile .kn-tart{display:block!important;position:relative;width:100%!important;max-width:100%!important;height:180px!important;min-height:0!important;margin:0!important;padding:0!important;overflow:hidden;background:#eee5d8;line-height:0}
