/* THEME FOOTER — TWO PAGE GROUPS START */
.site-footer{border-top:1px solid #6f4a2f;background:linear-gradient(125deg,#21170f,#2b1d13 70%,#322116);color:#e9d9c2}
.site-footer .footer-dir{display:block;width:100%;max-width:1180px;margin:0 auto;padding:clamp(34px,5vw,64px) clamp(22px,4vw,48px) 20px;text-align:left;box-sizing:border-box}
.site-footer .ft-intro{display:grid;grid-template-columns:1.25fr 1fr;gap:40px;align-items:start;padding-bottom:30px;border-bottom:1px solid #b58e5d36}
.site-footer .ft-identity>b{display:block;font:500 clamp(25px,3vw,34px)/1.25 'Playfair Display',Georgia,serif;color:#f7e9d5;letter-spacing:-.025em;margin:0 0 12px}
.site-footer .ft-identity>p,.site-footer .ft-contact p{font:400 12px/1.8 var(--font-body,Inter,Arial,sans-serif);color:#c6b49d;margin:0 0 18px;max-width:400px}
.site-footer .ft-identity .fd-soc{margin-top:18px}
.site-footer .ft-identity .fd-soc a{width:42px;height:42px;border-color:#8d6d4855;color:#e1b477}
.site-footer .ft-contact{padding-top:6px;justify-self:end;max-width:100%;min-width:0}
.site-footer .ft-eyebrow{display:block;font:600 9px/1.7 var(--font-body,Inter,Arial,sans-serif);text-transform:uppercase;letter-spacing:.18em;color:#d9a96d;margin:0 0 12px}
.site-footer a.ft-email{display:inline-block;font:500 13px/1.8 var(--font-body,Inter,Arial,sans-serif);color:#f2dfc4;text-decoration:none;overflow-wrap:anywhere;margin:0 0 10px;padding:4px 0;border-bottom:1px solid #b58e5d55}
.site-footer a.ft-email:hover{color:#fff1dc;border-bottom-color:#e7b97b}
.site-footer .ft-groups{display:grid;grid-template-columns:1.4fr 1fr;gap:clamp(30px,6vw,84px);padding-top:34px}
.site-footer .ft-group{min-width:0}
.site-footer .ft-group h2{font:500 clamp(24px,3vw,31px)/1.25 'Playfair Display',Georgia,serif;color:#f7e9d5;letter-spacing:-.025em;margin:0 0 20px}
.site-footer .ft-page-links{list-style:none;display:grid;grid-template-columns:1fr;gap:0 22px;margin:0;padding:0}
.site-footer .ft-explore .ft-page-links{grid-template-columns:repeat(2,minmax(0,1fr))}
.site-footer .ft-page-links li{margin:0;padding:0;min-width:0;list-style:none}
.site-footer .ft-page-links a{display:flex;align-items:center;justify-content:space-between;gap:14px;min-height:46px;box-sizing:border-box;padding:10px 0;color:#e8d7be;font:400 13px/1.6 var(--font-body,Inter,Arial,sans-serif);text-decoration:none;border-bottom:1px solid #b58e5d26;transition:color .2s,border-color .2s}
.site-footer .ft-page-links a::after{content:"\2192";font-size:15px;color:#b58c5b;transition:transform .2s;flex-shrink:0}
.site-footer .ft-page-links a:hover{color:#fff5e5;border-color:#c79860}
.site-footer .ft-page-links a:hover::after{transform:translateX(3px);color:#efbd7b}
.site-footer .ft-topics{margin-top:20px;color:#c6b49d;font:400 12px/1.8 var(--font-body,Inter,Arial,sans-serif)}
.site-footer .ft-topics summary{cursor:pointer;padding:10px 0;min-height:44px;box-sizing:border-box;color:#d9a96d;font-size:11px;letter-spacing:.02em}
.site-footer .ft-topics .fd-rooms{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px;margin:10px 0 0;padding:14px 0 0;border-top:1px solid #b58e5d26}
.site-footer .ft-topics a{display:block;min-height:40px;padding:8px 0;box-sizing:border-box;font:400 11px/1.6 var(--font-body,Inter,Arial,sans-serif);color:#cbb99f;text-decoration:none;overflow-wrap:anywhere}
.site-footer .ft-topics a:hover{color:#f5d09a;text-decoration:underline}
.site-footer .footer-attribution{border-top:1px solid #b58e5d26;margin-top:20px}
.site-footer :is(a,summary):focus-visible{outline:2px solid #ecc68c;outline-offset:5px;border-radius:2px}
@media(max-width:700px){
 .site-footer .ft-intro{grid-template-columns:1fr;gap:26px}
 .site-footer .ft-contact{justify-self:start;padding-top:0}
 .site-footer .ft-groups{grid-template-columns:1fr;gap:32px;padding-top:28px}
 .site-footer .ft-information{padding-top:28px;border-top:1px solid #b58e5d36}
 .site-footer .footer-dir{padding:34px 58px 18px 22px}
 .site-footer .ft-page-links a{font-size:12px;gap:9px;min-height:46px}
 .site-footer .ft-explore .ft-page-links{gap:0 18px}
 .site-footer .ft-group h2{font-size:27px}
 .site-footer .ft-contact p{margin-bottom:0}
}
@media(max-width:360px){
 .site-footer .footer-dir{padding-left:18px;padding-right:54px}
 .site-footer .ft-explore .ft-page-links{grid-template-columns:1fr}
 .site-footer .ft-topics .fd-rooms{grid-template-columns:1fr}
}
@media(max-width:640px){#page_list_top .kd-r1{gap:5px}#page_list_top .kd-n1{padding:6px 8px 6px 6px;gap:5px}#page_list_top .kd-n1 span{font-size:10.5px}#page_list_top .kd-n1 b{font-size:8px;padding:3px 3px}}
@media(prefers-reduced-motion:reduce){.site-footer a,.site-footer a::after{transition:none!important}}

/* THEME FOOTER — TWO PAGE GROUPS END */

/* THEME SEARCH DIALOG START */
/* ============ full-screen search dialog (overlay, never a page) ============ */
/* primary: light tone of the site copper swatch; warm-white cards; soft warm backdrop */
html.kvsd-lock{overflow:hidden}
.kvsd[hidden]{display:none!important}
.kvsd{position:fixed;inset:0;z-index:9999;display:grid;place-items:center;padding:clamp(8px,2.6vh,26px) clamp(8px,2.6vw,26px);font-family:var(--font-body,Inter,Arial,sans-serif)}
.kvsd-back{position:absolute;inset:0;background:rgba(112,56,26,.40);-webkit-backdrop-filter:blur(0px);backdrop-filter:blur(0px);opacity:0;transition:opacity .5s ease,-webkit-backdrop-filter .5s ease,backdrop-filter .5s ease}
.kvsd-open .kvsd-back{opacity:1;-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}
.kvsd-panel{position:relative;width:min(1120px,100%);height:min(92vh,900px);display:flex;flex-direction:column;background:linear-gradient(180deg,#F2C4A6,#EBB593);border:1px solid #D99B72;border-radius:22px;box-shadow:0 34px 80px -34px rgba(96,48,20,.55);overflow:hidden;opacity:0;transform:translateY(44px) scale(.92);transition:opacity .38s ease,transform .62s cubic-bezier(.34,1.56,.64,1)}
.kvsd-open .kvsd-panel{opacity:1;transform:none}
.kvsd-head{padding:clamp(18px,3vh,30px) clamp(18px,3.4vw,40px) 14px;border-bottom:1px solid rgba(150,80,40,.26)}
.kvsd-open .kvsd-head>*{animation:kvsdUp .55s cubic-bezier(.22,.7,.3,1) both}
.kvsd-open .kvsd-head>*:nth-child(2){animation-delay:.07s}
.kvsd-open .kvsd-head>*:nth-child(3){animation-delay:.14s}
.kvsd-open .kvsd-head>*:nth-child(4){animation-delay:.21s}
.kvsd-kick{display:inline-flex;align-items:center;gap:8px;font:700 10px/1 var(--font-body,Inter,Arial,sans-serif);letter-spacing:.3em;text-transform:uppercase;color:#8A4218;border:1px solid rgba(150,80,40,.38);background:rgba(255,248,241,.62);border-radius:999px;padding:7px 14px}
.kvsd-dot{width:6px;height:6px;border-radius:50%;background:#B4552D;animation:kvsdPulse 2.2s ease-in-out infinite}
.kvsd-head h2{font:800 clamp(24px,3.6vw,40px)/1.15 var(--font-display,'Playfair Display',Georgia,serif);color:#3E2210;letter-spacing:-.015em;margin:14px 0 16px}
.kvsd-bar{position:relative;display:flex;align-items:center;gap:10px;height:clamp(54px,7vh,66px);padding:0 8px 0 20px;border-radius:999px;border:1.5px solid #D89B77;background:#FFF8F1;box-shadow:0 8px 22px -14px rgba(96,48,20,.5);transition:border-color .25s,box-shadow .25s;overflow:hidden}
.kvsd-bar::after{content:"";position:absolute;top:0;bottom:0;left:-40%;width:34%;background:linear-gradient(100deg,rgba(255,255,255,0),rgba(255,255,255,.5),rgba(255,255,255,0));animation:kvsdShimmer 4.6s ease-in-out infinite;pointer-events:none}
.kvsd-bar:focus-within{border-color:#B4552D;box-shadow:0 0 0 4px rgba(180,85,45,.16)}
.kvsd-bar>svg{width:21px;height:21px;flex:0 0 auto;stroke:#9C4A1E;fill:none;stroke-width:2;stroke-linecap:round}
.kvsd-bar input{flex:1;min-width:0;height:100%;border:0;background:none;color:#3E2210;font:500 clamp(15px,1.6vw,18px)/1 var(--font-body,Inter,Arial,sans-serif);letter-spacing:.01em}
.kvsd-bar input:focus,.kvsd-bar input:focus-visible{outline:none}
.kvsd-bar input::-webkit-search-cancel-button,.kvsd-bar input::-webkit-search-decoration{-webkit-appearance:none;appearance:none}
.kvsd-bar input::placeholder{color:#9A6440}
.kvsd-go{flex:0 0 auto;height:calc(100% - 14px);margin:7px;border:0;border-radius:999px;padding:0 clamp(18px,2.4vw,30px);background:#B4552D;color:#FFF7EC;font:700 13px/1 var(--font-body,Inter,Arial,sans-serif);letter-spacing:.14em;text-transform:uppercase;cursor:pointer;transition:transform .25s cubic-bezier(.34,1.56,.64,1),background .2s;box-shadow:0 8px 18px -10px rgba(122,58,22,.7)}
.kvsd-go:hover{transform:translateY(-2px);background:#9C4522}
.kvsd-meta{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-top:12px;font:500 11px/1.5 var(--font-body,Inter,Arial,sans-serif);color:#7C4B2A}
.kvsd-chip{display:inline-flex;align-items:center;gap:7px;border:1px solid rgba(150,80,40,.38);background:rgba(255,248,241,.62);color:#8A4218;border-radius:999px;padding:5px 12px;font-weight:700;letter-spacing:.06em}
.kvsd-chip i{width:6px;height:6px;border-radius:50%;background:#B4552D;font-style:normal}
.kvsd-close{margin-left:auto;width:42px;height:42px;border-radius:50%;border:1px solid #D89B77;background:#FFF8F1;color:#9C4A1E;cursor:pointer;display:grid;place-items:center;transition:transform .3s cubic-bezier(.34,1.56,.64,1),background .2s}
.kvsd-close:hover{transform:rotate(90deg);background:#F8DEC9}
.kvsd-close svg{width:16px;height:16px;stroke:currentColor;stroke-width:2;stroke-linecap:round;fill:none}
.kvsd-body{flex:1;min-height:0;overflow-y:auto;padding:clamp(16px,2.6vh,26px) clamp(18px,3.4vw,40px) 30px;scrollbar-width:thin;scrollbar-color:#C98A63 transparent}
.kvsd-sec{margin:0 0 clamp(20px,3vh,30px)}
.kvsd-sechead{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:0 0 12px}
.kvsd-sechead h3{font:700 clamp(17px,2vw,21px)/1.2 var(--font-display,'Playfair Display',Georgia,serif);color:#3E2210;margin:0;position:relative;padding-bottom:8px}
.kvsd-sechead h3::after{content:"";position:absolute;left:0;bottom:0;width:44px;height:3px;border-radius:3px;background:#B4552D;transform-origin:left;animation:kvsdDraw .5s cubic-bezier(.22,.7,.3,1) .18s both}
.kvsd-sechead span{font:600 10.5px/1.4 var(--font-body,Inter,Arial,sans-serif);letter-spacing:.14em;text-transform:uppercase;color:#8A5A34}
.kvsd-open .kvsd-sec{animation:kvsdUp .6s cubic-bezier(.22,.7,.3,1) both}
.kvsd-open .kvsd-sec:nth-child(2){animation-delay:.09s}
.kvsd-open .kvsd-sec:nth-child(3){animation-delay:.18s}
/* right-to-left card marquees (reader's digest + daily headlines), cards carry photos */
.kvsd-mqwrap{position:relative;overflow:hidden;padding:6px 0 10px;margin:0 -6px}
.kvsd-mqwrap::before,.kvsd-mqwrap::after{content:"";position:absolute;top:0;bottom:0;width:46px;z-index:2;pointer-events:none}
.kvsd-mqwrap::before{left:0;background:linear-gradient(90deg,#EFBEA0,rgba(239,190,160,0))}
.kvsd-mqwrap::after{right:0;background:linear-gradient(270deg,#EFBEA0,rgba(239,190,160,0))}
.kvsd-mq{display:flex;gap:14px;width:max-content;animation:kvsdMQ 46s linear infinite;will-change:transform}
.kvsd-mqwrap:hover .kvsd-mq{animation-play-state:paused}
.kvsd-mqcard{width:272px;flex:0 0 auto;display:block;text-decoration:none;background:#FFF8F1;border:1px solid #DFA887;border-radius:16px;padding:12px 14px 14px;box-shadow:0 10px 22px -16px rgba(96,48,20,.55);transition:transform .35s cubic-bezier(.22,.7,.3,1),border-color .3s,box-shadow .35s;animation:kvsdPop .55s cubic-bezier(.22,.7,.3,1) both;animation-delay:calc(var(--i,0)*70ms)}
.kvsd-mqcard:hover{transform:translateY(-5px);border-color:#C98A63;box-shadow:0 18px 30px -16px rgba(96,48,20,.6)}
.kvsd-thumb{position:relative;display:block;height:112px;border-radius:10px;overflow:hidden;background:#F8DEC9;margin:0 0 10px}
.kvsd-thumb i{position:absolute;inset:0;display:grid;place-items:center;font:800 24px/1 var(--font-display,'Playfair Display',Georgia,serif);color:#C07A4E;font-style:normal;letter-spacing:.06em}
.kvsd-thumb img{position:relative;width:100%;height:100%;object-fit:cover;display:block}
.kvsd-mqcard b{display:block;font:700 10px/1 var(--font-body,Inter,Arial,sans-serif);letter-spacing:.16em;text-transform:uppercase;color:#B4552D;margin-bottom:7px}
.kvsd-mqcard span{display:block;font:600 13.5px/1.45 var(--font-body,Inter,Arial,sans-serif);color:#3E2210}
.kvsd-mqcard em{display:block;font-style:normal;font:500 11px/1.4 var(--font-body,Inter,Arial,sans-serif);color:#8A5A34;margin-top:7px}
.kvsd-empty{margin:0;padding:16px 18px;border:1.5px dashed #D3977A;border-radius:14px;background:rgba(255,248,241,.55);color:#7C4B2A;font:500 12.5px/1.6 var(--font-body,Inter,Arial,sans-serif)}
/* quick tool links: small, coloured, plain links */
.kvsd-quick{margin:0;font:600 12.5px/2.1 var(--font-body,Inter,Arial,sans-serif);color:#7C4B2A}
.kvsd-quick a{color:#9C4A1E;text-decoration:none;border-bottom:1px solid rgba(156,74,30,.4);padding:2px 1px;margin:0 2px;transition:color .2s,border-color .2s}
.kvsd-quick a:hover{color:#7A3512;border-bottom-color:#7A3512}
.kvsd-quick i{font-style:normal;color:#B4552D;margin:0 7px 0 9px}
/* live suggestion groups */
.kvsd-list{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.kvsd-list li{margin:0;animation:kvsdUp .45s cubic-bezier(.22,.7,.3,1) both;animation-delay:calc(var(--i,0)*60ms)}
.kvsd-list a{display:flex;align-items:center;gap:14px;padding:10px 14px;border:1px solid #DFA887;border-radius:14px;background:#FFF8F1;text-decoration:none;transition:transform .28s cubic-bezier(.22,.7,.3,1),border-color .22s,box-shadow .28s}
.kvsd-list a:hover{transform:translateX(6px);border-color:#C98A63;box-shadow:0 10px 22px -16px rgba(96,48,20,.55)}
.kvsd-rowthumb{position:relative;flex:0 0 auto;width:46px;height:46px;border-radius:10px;overflow:hidden;background:#F8DEC9}
.kvsd-rowthumb i{position:absolute;inset:0;display:grid;place-items:center;font:800 15px/1 var(--font-display,'Playfair Display',Georgia,serif);color:#C07A4E;font-style:normal}
.kvsd-rowthumb img{position:relative;width:100%;height:100%;object-fit:cover;display:block}
.kvsd-list .kvsd-main{flex:1;min-width:0}
.kvsd-list .kvsd-name{display:block;font:600 14px/1.4 var(--font-body,Inter,Arial,sans-serif);color:#3E2210}
.kvsd-list .kvsd-sub{display:block;font:500 11.5px/1.5 var(--font-body,Inter,Arial,sans-serif);color:#8A5A34;margin-top:3px}
.kvsd-list .kvsd-tag{flex:0 0 auto;font:700 9.5px/1 var(--font-body,Inter,Arial,sans-serif);letter-spacing:.14em;text-transform:uppercase;color:#8A4218;border:1px solid #DFA887;background:#F8DEC9;border-radius:999px;padding:6px 10px}
.kvsd-list .kvsd-count{flex:0 0 auto;font:700 10.5px/1 var(--font-body,Inter,Arial,sans-serif);color:#9C4A1E;background:rgba(180,85,45,.14);border-radius:999px;padding:6px 10px}
.kvsd-list .kvsd-arrow{flex:0 0 auto;color:#B4713D;font-size:15px;transition:transform .25s,color .25s}
.kvsd-list a:hover .kvsd-arrow{transform:translateX(4px);color:#B4552D}
.kvsd-list mark{background:rgba(180,85,45,.25);color:inherit;border-radius:2px;padding:0 1px}
.kvsd-none{padding:12px 16px;border:1.5px dashed #D3977A;border-radius:14px;background:rgba(255,248,241,.55);color:#7C4B2A;font:500 12.5px/1.6 var(--font-body,Inter,Arial,sans-serif)}
.kvsd-more{display:inline-block;margin:14px 0 0;color:#9C4A1E;font:600 12px/1.4 var(--font-body,Inter,Arial,sans-serif);text-decoration:none;border-bottom:1px solid rgba(156,74,30,.4)}
.kvsd-more:hover{border-bottom-color:#7A3512;color:#7A3512}
.kvsd :is(a,button):focus-visible{outline:2px solid #9C4A1E;outline-offset:3px;border-radius:6px}
@keyframes kvsdMQ{from{transform:translateX(0)}to{transform:translateX(-50%)}}
@keyframes kvsdUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@keyframes kvsdPop{from{opacity:0;transform:translateY(18px) scale(.94)}to{opacity:1;transform:none}}
@keyframes kvsdDraw{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes kvsdShimmer{0%{left:-40%}55%{left:120%}100%{left:120%}}
@keyframes kvsdPulse{0%,100%{transform:scale(1);opacity:1}50%{transform:scale(1.5);opacity:.55}}
@media(max-width:700px){
 .kvsd{padding:0}
 .kvsd-panel{width:100%;height:100vh;height:100dvh;border-radius:0;border:0}
 .kvsd-head{padding:16px 16px 12px}
 .kvsd-head h2{margin:12px 0 12px;font-size:24px}
 .kvsd-body{padding:14px 16px 26px}
 .kvsd-mqcard{width:236px}
 .kvsd-thumb{height:96px}
 .kvsd-close{width:40px;height:40px}
}
@media(max-width:640px){#page_list_top .kd-r1{gap:5px}#page_list_top .kd-n1{padding:6px 8px 6px 6px;gap:5px}#page_list_top .kd-n1 span{font-size:10.5px}#page_list_top .kd-n1 b{font-size:8px;padding:3px 3px}}
@media(prefers-reduced-motion:reduce){
 .kvsd-panel,.kvsd-back,.kvsd-open .kvsd-sec,.kvsd-open .kvsd-head>*,.kvsd-list li,.kvsd-mqcard{animation:none!important;transition-duration:.01s!important}
 .kvsd-mq{animation:none!important}
 .kvsd-mqwrap{overflow-x:auto;-webkit-overflow-scrolling:touch}
 .kvsd-dot,.kvsd-bar::after,.kvsd-sechead h3::after{animation:none!important}
 .kvsd-sechead h3::after{transform:none}
}

/* THEME SEARCH DIALOG END */

/* THEME FAB STACK START */
.fab-stack [data-tip]{position:relative}
@media(hover:hover){
 .fab-stack [data-tip]:hover::after,.fab-stack [data-tip]:focus-visible::after{content:attr(data-tip);position:absolute;right:calc(100% + 12px);top:50%;transform:translateY(-50%);background:#241610;color:#F8F0E3;font:600 10px/1 var(--font-body,Inter,Arial,sans-serif);letter-spacing:.1em;text-transform:uppercase;padding:8px 11px;border-radius:8px;white-space:nowrap;box-shadow:0 10px 24px -12px rgba(36,22,16,.7);pointer-events:none;animation:kcTip .25s cubic-bezier(.22,.7,.3,1) both}
 @keyframes kcTip{from{opacity:0;transform:translateY(-50%) translateX(6px)}to{opacity:1;transform:translateY(-50%)}}
}
@media(hover:none){.fab-stack [data-tip]::after{content:none}}
@media(max-height:620px){.fab-stack{gap:5px}.fab,.fab-stack #toTop{width:36px;height:36px}.fab svg{width:15px;height:15px}}
/* THEME FAB STACK END */

/* KC-HOME-V3: generic page-chrome styling (announcement/toolbar sit outside page scopes) */
.enh-announcement{display:flex;align-items:center;justify-content:space-between;gap:12px;border-block:1px dashed #d8bc99;padding:13px 18px;background:#f2dfbf40;margin:20px 0;color:#8a5233;font:500 11px/1.8 Inter,Arial,sans-serif;border-radius:10px}
.enh-announcement a{color:#9c4522;font-weight:700;text-decoration:none;white-space:nowrap}
.enh-toolbar{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:10px 8px;margin-bottom:8px;border-bottom:1px dashed #d9c4a4;color:#947557;font:600 9px/1.5 Inter,Arial,sans-serif;letter-spacing:.1em;text-transform:uppercase}
.enh-toolbar a{color:inherit;text-decoration:none}
.enh-effects{font:600 10px/1.5 Inter,Arial,sans-serif;padding:7px 12px;border:1px solid #d9c4a4;background:#fff9ee;color:#8a4429;border-radius:30px;cursor:pointer;white-space:nowrap}
.kh-still{animation:none!important;transform:none!important;flex-wrap:wrap;justify-content:center;width:100%;max-width:100%}
/* KC-HOME-V3: mobile nav legibility — FIXED: scrollable tabs, no clipping */
@media (max-width:860px){
 /* Nav container takes full width, no side padding */
 #page_list_top .kd-nav {
 padding-left: 0 !important;
 padding-right: 0 !important;
 margin-left: 0;
 margin-right: 0;
 max-width: 100% !important;
 width: 100%;
 }
 /* Top tab row: full width, horizontal scroll */
 #page_list_top .kd-r1{
 gap:6px;
 padding:8px 60px 6px 16px; /* left 16px, right 60px to clear floating action buttons */
 width:100% !important;
 max-width:100% !important;
 margin:0 !important;
 overflow-x:auto !important;
 overflow-y:hidden;
 scrollbar-width:none;
 -webkit-overflow-scrolling:touch;
 overscroll-behavior-x:contain;
 box-sizing:border-box;
 justify-content:flex-start;
 }
 #page_list_top .kd-r1::-webkit-scrollbar{display:none}
 /* Tab items keep natural size, don't grow/shrink */
 #page_list_top .kd-r1 li {
 flex: 0 0 auto !important;
 }
 #page_list_top .kd-n1{
 flex: 0 0 auto !important; /* don't stretch to fill container */
 padding:8px 10px 8px 8px;
 gap:6px;
 background:#FFFDF8!important;
 border:1px solid #D9B98F!important;
 border-radius:12px;
 box-shadow:0 2px 6px -3px rgba(36,22,16,.25);
 }
 #page_list_top .kd-n1 span{
 font-size:11px!important;
 font-weight:800!important;
 color:#241610!important;
 letter-spacing:.06em!important;
 white-space:nowrap!important; /* prevent text wrapping inside tabs */
 }
 #page_list_top .kd-n1 b{
 font-size:8.5px!important;
 padding:3px 4px!important;
 background:#BC5B33!important;
 color:#FFFDF8!important;
 border-radius:6px;
 flex:0 0 auto;
 }
 #page_list_top .kd-n1 em{display:none} /* disable shine effect on mobile for performance */
 /* Secondary footer link row: full width, horizontal scroll */
 #page_list_top .kd-r2{
 flex-wrap:nowrap!important;
 justify-content:flex-start!important;
 max-width:100%!important;
 width:100%!important;
 margin:0!important;
 overflow-x:auto!important;
 overflow-y:hidden;
 scrollbar-width:none;
 -webkit-overflow-scrolling:touch;
 overscroll-behavior-x:contain;
 padding:2px 60px 10px 16px; /* left 16px, right 60px to clear floating action buttons */
 box-sizing:border-box;
 }
 #page_list_top .kd-r2::-webkit-scrollbar{display:none}
 #page_list_top .kd-r2 li {
 flex:0 0 auto !important;
 }
 #page_list_top .kd-r2 a{
 font-size:9.5px!important;
 padding:7px 6px!important;
 color:#6E4A2F!important;
 white-space:nowrap!important;
 }
}
@media (max-width:560px){
 /* Smaller phones: slightly tighter spacing */
 #page_list_top .kd-r1{
 padding:8px 52px 6px 12px;
 gap:5px;
 }
 #page_list_top .kd-n1{
 padding:7px 9px 7px 7px;
 gap:5px;
 }
 #page_list_top .kd-n1 span{font-size:10.5px!important}
 #page_list_top .kd-n1 b{font-size:8px!important;padding:2px 4px!important}
 #page_list_top .kd-r2{
 padding:2px 52px 8px 12px;
 gap:4px;
 }
}
/* KC-HOME-V3: market pulse strip */
.kh-pulse{display:flex;align-items:center;gap:10px;margin:10px auto 2px;padding:8px 12px;background:linear-gradient(90deg,#FBF1E5,#F6E7D2);border:1px dashed #D9B98F;border-radius:14px}
.kh-plab{flex:0 0 auto;font:800 9px/1 Inter,Arial,sans-serif;letter-spacing:.22em;text-transform:uppercase;color:#BC5B33;background:#FFFDF8;border:1px solid #E3C9A4;border-radius:999px;padding:6px 10px}
.kh-ptrack{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch;flex:1 1 auto}
.kh-ptrack::-webkit-scrollbar{display:none}
.kh-pchip{flex:0 0 auto;display:inline-flex;align-items:baseline;gap:6px;font:700 11px/1 Inter,Arial,sans-serif;color:#241610;background:#FFFDF8;border:1px solid #EADCC8;border-radius:10px;padding:7px 10px;font-variant-numeric:tabular-nums}
.kh-pchip b{font:800 9px/1 Inter,Arial,sans-serif;letter-spacing:.12em;color:#6E5D4B}
.kh-pchip i{font-style:normal;font:800 9.5px/1 Inter,Arial,sans-serif}
.kh-pchip i.up{color:#2F7A46}.kh-pchip i.dn{color:#B3402E}
.kh-pwait{color:#8A6B47;font-weight:600}
/* KC-HOME-V3: home calculator bench */
.kh-tools{margin:26px auto 6px;padding:20px 16px 16px;background:#FFFDF8;border:1px solid #EADCC8;border-radius:20px;box-shadow:0 22px 44px -30px rgba(36,22,16,.35)}
.kh-tkick{display:inline-block;font:800 9px/1 Inter,Arial,sans-serif;letter-spacing:.22em;text-transform:uppercase;color:#BC5B33;border:1px dashed #BC5B33;background:#FBF1E5;border-radius:999px;padding:6px 11px}
.kh-th2{font:900 clamp(20px,3.4vw,30px)/1.15 'Playfair Display',Georgia,serif;color:#241610;margin:10px 0 14px}
.kh-tgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
@media (max-width:820px){.kh-tgrid{grid-template-columns:1fr}}
.kh-tcard{background:#F8F0E3;border:1px dashed #E3D3B3;border-radius:14px;padding:14px 13px 12px;display:flex;flex-direction:column;gap:8px}
.kh-tcard>b{font:800 12px/1.3 'Playfair Display',Georgia,serif;color:#9C4522}
.kh-tcard label{display:flex;justify-content:space-between;align-items:center;gap:8px;font:600 10px/1.4 Inter,Arial,sans-serif;letter-spacing:.06em;color:#6E5D4B;text-transform:uppercase}
.kh-tcard input{width:110px;font:700 12px/1.2 Inter,Arial,sans-serif;color:#241610;background:#FFFDF8;border:1px solid #D9C4A4;border-radius:8px;padding:6px 8px;text-align:right}
.kh-tcard output{font:800 19px/1.25 'Playfair Display',Georgia,serif;color:#241610;font-variant-numeric:tabular-nums}
.kh-tcard i{font:500 15px/1.3 Caveat,'Segoe Script',cursive;color:#6E5D4B}
.kh-tfine{margin:12px 2px 0;font:400 10.5px/1.6 Inter,Arial,sans-serif;color:#7A6854}
/* KC-FULLWIDTH v1 : every shell spans 100% of the screen width */
.item-post .post-body,.page-body{padding-left:0;padding-right:0;}
.kv-hero{padding-left:0;padding-right:0;}
#page_list_top .kd-nav{max-width:none;}
#enhancedHome{max-width:none;margin-left:0;margin-right:0;}
.post-body #enhancedHome{max-width:none!important;}
.site-footer .footer-dir{max-width:none;}
/* KC-FULLWIDTH v2 : theme-enforced 100% width for every present & future page/post */
.page-body>*,.page-body>*>*,.page-body>*>*>*,.post-body>*,.post-body>*>*,.post-body>*>*{max-width:none!important;margin-left:0!important;margin-right:0!important;}
.pr-page,.wrap,.kpg,.knews,#articleHub,.tl,.principles,.who,#enhancedSite,.enh-original,
#enhancedSite .pr-page,#enhancedSite .wrap,#enhancedSite .kpg,#enhancedSite .knews,#enhancedSite #articleHub,
#enhancedSite .tl,#enhancedSite .principles,#enhancedSite .who{max-width:none!important;margin-left:0!important;margin-right:0!important;padding-left:0!important;padding-right:0!important;}
html,body{overflow-x:clip!important;}
/* THEME HOME DESK START — KC-HOME-DESK v1 : two-row nav + front-desk homepage */
#page_list_top .kd-nav{max-width:1240px;margin:16px auto 6px;padding:10px 12px 4px;text-align:center;}
#page_list_top .kd-r1{display:flex;flex-wrap:nowrap;gap:8px;list-style:none;margin:0 auto;padding:6px 4px 4px;width:max-content;max-width:100%;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch;counter-reset:kd;}
#page_list_top .kd-r1::-webkit-scrollbar{display:none;}
#page_list_top .kd-r1{align-items:stretch;}
#page_list_top .kd-r1 li{display:flex;}
#page_list_top .kd-n1{flex:1 1 auto;}
#page_list_top .kd-r1 li{counter-increment:kd;}
#page_list_top .kd-n1{position:relative;display:flex;align-items:center;gap:8px;padding:8px 12px 8px 9px;border-radius:12px;text-decoration:none;
 background:linear-gradient(140deg,#FFFDF8,#FBF3E2);border:1px solid #E6D3B4;box-shadow:0 10px 24px -18px rgba(70,42,20,.5);
 overflow:hidden;transform:translateY(0);transition:transform .35s cubic-bezier(.22,.7,.3,1),box-shadow .35s ease,border-color .3s ease;
 animation:kdPop .7s cubic-bezier(.34,1.4,.64,1) both;animation-delay:calc(var(--kdi,0)*90ms);}
#page_list_top .kd-r1 li:nth-child(1) .kd-n1{--kdi:0}#page_list_top .kd-r1 li:nth-child(2) .kd-n1{--kdi:1}#page_list_top .kd-r1 li:nth-child(3) .kd-n1{--kdi:2}
#page_list_top .kd-r1 li:nth-child(4) .kd-n1{--kdi:3}#page_list_top .kd-r1 li:nth-child(5) .kd-n1{--kdi:4}#page_list_top .kd-r1 li:nth-child(6) .kd-n1{--kdi:5}
#page_list_top .kd-n1 b{font:700 9px/1 Inter,Arial,sans-serif;letter-spacing:.07em;color:#BC5B33;background:#F6E8CF;border:1px solid #EAD7B4;border-radius:7px;padding:4px 5px;}
#page_list_top .kd-n1 b::before{content:counter(kd,decimal-leading-zero);}
#page_list_top .kd-n1 span{min-height:2.4em;display:block;text-align:left;white-space:normal;font:600 12.5px/1.2 'Playfair Display',Georgia,serif;color:#241610;letter-spacing:.01em;}
#page_list_top .kd-n1 em{position:absolute;top:0;bottom:0;width:38%;left:-45%;background:linear-gradient(100deg,transparent,rgba(255,248,235,.75),transparent);transform:skewX(-18deg);animation:kdShine 5.5s ease-in-out infinite;animation-delay:calc(var(--kdi,0)*700ms);}
#page_list_top .kd-n1:hover{transform:translateY(-4px);border-color:#D9BF94;box-shadow:0 18px 34px -20px rgba(120,70,30,.55);}
#page_list_top .kd-r2{display:flex;flex-wrap:wrap;justify-content:center;gap:4px 6px;list-style:none;margin:2px auto 0;padding:0;max-width:920px;}
#page_list_top .kd-r2 li{display:flex;align-items:center;}
#page_list_top .kd-r2 li+li::before{content:"\B7";color:#C7AE87;margin:0 7px;}
#page_list_top .kd-r2 a{font:600 10.5px/1.4 Inter,Arial,sans-serif;letter-spacing:.14em;text-transform:uppercase;color:#8A6B47;text-decoration:none;padding:6px 4px;border-bottom:1px solid transparent;transition:color .25s ease,border-color .25s ease;}
#page_list_top .kd-r2 a:hover{color:#BC5B33;border-color:#D9BF94;}
@keyframes kdPop{from{opacity:0;transform:translateY(14px) scale(.94)}to{opacity:1;transform:none}}
@keyframes kdShine{0%,72%{left:-45%}88%,100%{left:115%}}
.kd-sec{max-width:1080px;margin:clamp(26px,4vw,44px) auto 0;padding:0 clamp(14px,3vw,28px);}
.kd-head{ text-align:center;}
.kd-kick{display:inline-block;font:700 9.5px/1.5 Inter,Arial,sans-serif;letter-spacing:.3em;text-transform:uppercase;color:#BC5B33;border:1px solid #E3D3B3;background:#FBF6EC;border-radius:999px;padding:6px 14px;}
.kd-head h2{font:800 clamp(20px,3vw,27px)/1.2 'Playfair Display',Georgia,serif;color:#241610;margin:12px 0 6px;}
.kd-lede{font:400 12.5px/1.7 Inter,Arial,sans-serif;color:#6E5D4B;max-width:560px;margin:0 auto;}
.kd-rowlab{display:flex;align-items:center;gap:10px;font:700 10px/1 Inter,Arial,sans-serif;letter-spacing:.22em;text-transform:uppercase;color:#98744C;margin:20px 2px 8px;}
.kd-rowlab::after{content:"";flex:1;border-top:1px dashed #DCC9A8;}
.kd-row{display:flex;gap:14px;overflow-x:auto;padding:4px 2px 12px;scroll-snap-type:x proximity;-webkit-overflow-scrolling:touch;scrollbar-width:thin;scrollbar-color:#D8C6A4 transparent;}
.kd-row::-webkit-scrollbar{height:6px}.kd-row::-webkit-scrollbar-thumb{background:#D8C6A4;border-radius:8px}
.kd-card{flex:0 0 250px;scroll-snap-align:start;display:block;text-decoration:none;background:#FFFDF8;border:1px solid #EADCC8;border-radius:14px;overflow:hidden;transition:transform .35s ease,box-shadow .35s ease,border-color .3s ease;}
.kd-card:hover{transform:translateY(-4px);border-color:#D9BF94;box-shadow:0 18px 34px -22px rgba(90,50,20,.5);}
.kd-card .kd-th{height:110px;background:linear-gradient(135deg,#F6EBD4,#EFE0C0);display:flex;align-items:center;justify-content:center;font:900 30px/1 'Playfair Display',Georgia,serif;color:rgba(156,94,44,.75);}
.kd-card .kd-th img{width:100%;height:100%;object-fit:cover;display:block;}
.kd-card b{display:block;font:700 12.5px/1.4 'Playfair Display',Georgia,serif;color:#241610;padding:10px 12px 2px;}
.kd-card i{display:block;font:400 10.5px/1.5 Inter,Arial,sans-serif;color:#8A7458;padding:0 12px 12px;font-style:normal;}
.kd-empty{flex:0 0 auto;max-width:420px;background:#FBF6EC;border:1.5px dashed #D9C6A2;border-radius:14px;padding:18px 20px;font:400 12px/1.65 Inter,Arial,sans-serif;color:#7A6A58;}
.kd-empty b{display:block;font:700 14px/1.3 'Playfair Display',Georgia,serif;color:#241610;margin-bottom:4px;}
.kd-ref{text-align:center;margin:14px 0 0;}
.kd-ref a{display:inline-block;font:700 11.5px/1 Inter,Arial,sans-serif;letter-spacing:.06em;color:#9C4522;text-decoration:none;border:1px solid #E3D3B3;background:#FBF6EC;border-radius:999px;padding:10px 18px;transition:transform .3s ease,color .25s ease,border-color .25s ease;}
.kd-ref a:hover{transform:translateY(-2px);color:#BC5B33;border-color:#D9BF94;}
.kd-mqwrap{position:relative;overflow:hidden;padding:6px 0 10px;}
.kd-mqwrap::before,.kd-mqwrap::after{content:"";position:absolute;top:0;bottom:0;width:46px;z-index:3;pointer-events:none;}
.kd-mqwrap::before{left:0;background:linear-gradient(90deg,rgba(252,246,235,.95),rgba(252,246,235,0));}
.kd-mqwrap::after{right:0;background:linear-gradient(270deg,rgba(252,246,235,.95),rgba(252,246,235,0));}
.kd-mq{display:flex;gap:14px;width:max-content;will-change:transform;}
.kd-mqwrap:hover .kd-mq{cursor:grab;}
.kd-mqwrap.kd-grabbing .kd-mq{cursor:grabbing;}
.kd-tabs{display:flex;gap:12px;width:max-content;will-change:transform;padding:4px 2px 10px;}
.kd-tabswrap{position:relative;overflow:hidden;}
.kd-tabswrap:hover .kd-tabs{cursor:grab;}
.kd-tabswrap.kd-grabbing .kd-tabs{cursor:grabbing;}
.kd-tab{flex:0 0 auto;display:flex;align-items:center;gap:10px;padding:10px 16px 10px 12px;background:#FFFDF8;border:1px solid #E6D3B4;border-radius:999px;text-decoration:none;transition:transform .3s ease,border-color .25s ease,box-shadow .3s ease;}
.kd-tab:hover{transform:translateY(-3px);border-color:#D9BF94;box-shadow:0 14px 26px -18px rgba(110,64,26,.5);}
.kd-tab svg{width:26px;height:26px;fill:none;stroke:#9C4522;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;}
.kd-tab b{display:block;font:700 12.5px/1.2 'Playfair Display',Georgia,serif;color:#241610;}
.kd-tab i{display:block;font:400 10px/1.4 Inter,Arial,sans-serif;color:#8A7458;font-style:normal;}
.kd-about{text-align:center;}
.kd-about-line{font:500 clamp(22px,3.6vw,34px)/1.3 'Playfair Display',Georgia,serif;color:#241610;margin:0;}
.kd-about-line b{color:#BC5B33;font-style:italic;display:inline-block;min-width:5.2ch;transition:opacity .4s ease,transform .4s ease;}
.kd-about-line b.kd-out{opacity:0;transform:translateY(8px);}
.kd-about-txt{font:400 12.5px/1.8 Inter,Arial,sans-serif;color:#6E5D4B;max-width:640px;margin:10px auto 0;}
.kd-digest{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;}
.kd-dg{display:block;text-decoration:none;background:#FFFDF8;border:1px solid #EADCC8;border-radius:16px;padding:18px 16px;transition:transform .3s ease,border-color .25s ease,box-shadow .3s ease;}
.kd-dg:hover{transform:translateY(-4px);border-color:#D9BF94;box-shadow:0 18px 32px -22px rgba(90,50,20,.5);}
.kd-dg b{display:block;font:800 14px/1.3 'Playfair Display',Georgia,serif;color:#241610;margin-bottom:6px;}
.kd-dg span{display:block;font:400 11px/1.6 Inter,Arial,sans-serif;color:#6E5D4B;margin-bottom:10px;}
.kd-dg i{font:700 10px/1 Inter,Arial,sans-serif;letter-spacing:.1em;text-transform:uppercase;color:#9C4522;font-style:normal;}
.kd-engage{text-align:center;background:linear-gradient(160deg,#FBF3E2,#F6E8CF);border:1px solid #EAD7B4;border-radius:20px;padding:clamp(20px,3.4vw,34px);}
.kd-engage h2{font:800 clamp(19px,2.6vw,25px)/1.25 'Playfair Display',Georgia,serif;color:#241610;margin:0 0 8px;}
.kd-engage p{font:400 12.5px/1.7 Inter,Arial,sans-serif;color:#6E5D4B;max-width:520px;margin:0 auto;}
.kd-eg-row{display:flex;flex-wrap:wrap;justify-content:center;gap:10px;margin:16px 0 8px;}
.kd-eg{font:600 11.5px/1 Inter,Arial,sans-serif;color:#9C4522;text-decoration:none;border:1px solid #DFC79E;background:#FFFDF8;border-radius:999px;padding:10px 16px;transition:transform .3s ease,border-color .25s ease;}
.kd-eg:hover{transform:translateY(-2px);border-color:#C9962E;}
.kd-eg-fine{font:400 10.5px/1.6 Inter,Arial,sans-serif;color:#93805F;}
.kd-legal{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;}
.kd-lg{background:#FBF6EC;border:1px dashed #D9C6A2;border-radius:16px;padding:16px 18px;}
.kd-lg b{display:block;font:700 12.5px/1.3 'Playfair Display',Georgia,serif;color:#241610;margin-bottom:6px;}
.kd-lg p{font:400 11px/1.65 Inter,Arial,sans-serif;color:#6E5D4B;margin:0 0 8px;}
.kd-lg a{font:700 10.5px/1 Inter,Arial,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:#9C4522;text-decoration:none;}
@media(max-width:860px){.kd-digest{grid-template-columns:repeat(2,minmax(0,1fr));}}
@media(max-width:640px){#page_list_top .kd-r1{gap:6px}#page_list_top .kd-n1{padding:7px 10px 7px 8px;gap:6px;border-radius:11px}#page_list_top .kd-n1 span{font-size:11.5px}#page_list_top .kd-n1 b{font-size:8.5px;padding:3px 4px}.kd-legal{grid-template-columns:1fr}.kd-digest{grid-template-columns:1fr 1fr;gap:10px}}
@media(max-width:640px){#page_list_top .kd-r1{gap:5px}#page_list_top .kd-n1{padding:6px 8px 6px 6px;gap:5px}#page_list_top .kd-n1 span{font-size:10.5px}#page_list_top .kd-n1 b{font-size:8px;padding:3px 3px}}
@media(prefers-reduced-motion:reduce){#page_list_top .kd-n1, #page_list_top .kd-n1 em{animation:none}}

#page_list_top .kd-r1 a::after,#page_list_top .kd-r2 a::after{content:none;}
#page_list_top .kd-nav .widget-title,#page_list_top .kd-nav h2.title{display:none;}
.kd-tab,.kd-tab svg,.kd-news .kd-card{-webkit-user-drag:none;user-select:none;-webkit-user-select:none;}
/* THEME HOME DESK END */

/* DAILY YIELD identity: classic theme, minimal override */
.topbar-title{flex-direction:column!important;gap:1px!important;padding:2px 0 12px!important;line-height:1!important;overflow:visible!important}
.topbar-title .tb-a{font:800 clamp(20px,3vw,30px)/1.05 var(--font-display);letter-spacing:.1em;color:var(--ink)}
.topbar-title .tb-line{min-height:20px;align-items:center;justify-content:center}
.topbar-title .tb-b{font:400 clamp(15px,2vw,19px)/1 var(--font-hand);letter-spacing:.025em;color:var(--accent);text-transform:none}
.topbar-title .tb-caret{height:15px}
.tb-squig{bottom:-7px;width:clamp(64px,7vw,90px)}
.ft-by{display:block;margin:3px 0 8px;font:400 17px/1.2 var(--font-hand);color:var(--muted)}
@media(max-width:560px){.topbar-title .tb-a{font-size:19px}.topbar-title .tb-b{font-size:15px}}

/* DY_SUBSCRIPTION_CSS_START */
.dy-follow-lock,.dy-follow-lock body{overflow:hidden!important}.dy-follow-lock body::before{content:"";position:fixed;z-index:235;inset:0;background:rgba(248,240,227,.22);-webkit-backdrop-filter:blur(13px) saturate(.78);backdrop-filter:blur(13px) saturate(.78);pointer-events:auto}
.dy-follow-popup{position:fixed;z-index:240;left:50%;top:50%;width:min(560px,calc(100% - 28px));transform:translate(-50%,-50%);padding:clamp(30px,5vw,42px);text-align:center;border:1px solid #d9b985;border-radius:26px;background:rgba(255,248,239,.95);box-shadow:0 38px 120px rgba(56,31,15,.40);-webkit-backdrop-filter:blur(18px);backdrop-filter:blur(18px);display:none;overflow:hidden}.dy-follow-popup.dy-open{display:block}.dy-follow-popup::before{content:"";position:absolute;inset:0;border-radius:inherit;background:linear-gradient(120deg,rgba(255,255,255,.68),transparent 48%);pointer-events:none}.dy-follow-popup>*{position:relative}
.dy-follow-close{position:absolute;z-index:2;right:14px;top:14px;width:40px;height:40px;display:grid;place-items:center;border:1px solid #dbc6aa;border-radius:50%;background:rgba(255,255,255,.78);color:#4e392b;font:500 24px/1 var(--font-body)}
.dy-follow-icon{width:62px;height:62px;margin:0 auto 17px;border-radius:19px;display:grid;place-items:center;color:#fff;background:linear-gradient(145deg,var(--accent),var(--accent-dark));box-shadow:0 14px 28px -16px rgba(156,69,34,.9)}.dy-follow-icon svg{width:30px;height:30px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.dy-follow-kicker{margin:0 44px 10px;color:var(--accent-dark);font:800 9px/1.3 var(--font-body);letter-spacing:.2em;text-transform:uppercase}.dy-follow-popup h2{margin:0 36px 0;color:var(--ink);font:700 clamp(31px,5vw,44px)/1.06 var(--font-display);letter-spacing:-.035em}.dy-follow-copy{max-width:430px;margin:14px auto 22px;color:var(--muted);font-size:13px;line-height:1.65}
.dy-follow-button{display:flex;width:100%;min-height:62px;align-items:center;justify-content:center;gap:10px;border:1px solid var(--accent-dark);border-radius:15px;background:linear-gradient(120deg,var(--accent-dark),var(--accent),#d67c50);color:#fff8ee;font:800 15px/1 var(--font-body);letter-spacing:.06em;text-transform:uppercase;box-shadow:0 16px 32px -18px rgba(156,69,34,.9);transition:transform .25s,box-shadow .25s}.dy-follow-button:hover{transform:translateY(-2px);box-shadow:0 19px 36px -17px rgba(156,69,34,.95)}.dy-follow-button svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:1.8}.dy-follow-note{margin:13px 0 0;color:#887664;font-size:10px;line-height:1.45}
@media(max-width:560px){.dy-follow-popup{width:calc(100% - 18px);padding:29px 19px 24px}.dy-follow-popup h2{font-size:31px;margin-inline:26px}.dy-follow-close{right:10px;top:10px}.dy-follow-button{min-height:58px}}
@media(prefers-reduced-motion:reduce){.dy-follow-button{transition:none}}
/* DY_SUBSCRIPTION_CSS_END */
/* DY_SITE_ENHANCEMENTS_CSS_START */
:root{color-scheme:light;--dy-focus:#0b66c3}
/* Full-screen selected Option 1: a dense, dependency-free finance sticker wall
   with one lightweight centre-ring animation and one composited field drift. */
.dy-load-screen{position:fixed;inset:0;z-index:2147483000;display:grid;place-items:center;overflow:hidden;isolation:isolate;contain:strict;background:radial-gradient(circle at 50% 42%,#fffaf1 0,#f8ecda 58%,#efd8bd 100%);color:#241610;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .24s ease-out,visibility 0s linear .24s;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}
.dy-load-screen[data-active='true']{opacity:1;visibility:visible;pointer-events:auto;transition:opacity .22s ease-out,visibility 0s;animation:dyLoaderFadeIn .24s ease-out both}.dy-symbol-field{position:absolute;z-index:0;inset:-6%;display:grid;grid-template-columns:repeat(12,minmax(58px,1fr));grid-template-rows:repeat(9,minmax(58px,1fr));align-items:center;justify-items:center;gap:5px;transform:rotate(-3deg) scale(1.07);animation:dyFieldDrift 5s ease-in-out infinite;will-change:transform}.dy-symbol-field span{display:grid;place-items:center;min-width:42px;min-height:42px;padding:5px;color:#9c4522;font:800 clamp(20px,3vw,42px)/1 Georgia,"Times New Roman",serif;opacity:.18}.dy-symbol-field span:nth-child(3n){color:#315d4b;transform:rotate(8deg)}.dy-symbol-field span:nth-child(4n){color:#bc7d22;transform:rotate(-9deg)}.dy-symbol-field span:nth-child(5n){border:1px solid currentColor;border-radius:12px;background:rgba(255,253,248,.42);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;font-size:clamp(10px,1.5vw,17px);letter-spacing:.04em}.dy-symbol-field span:nth-child(7n){border-radius:50%;outline:1px solid currentColor;outline-offset:5px}
.dy-sticker-field{position:absolute;z-index:2;inset:0;pointer-events:none}.dy-sticker{--s:1;position:absolute;display:flex;align-items:center;justify-content:center;gap:7px;padding:9px 13px;border:2px solid currentColor;border-radius:15px;background:#fffdf8;color:#9c4522;box-shadow:4px 6px 0 rgba(36,22,16,.13);font:800 clamp(10px,1.25vw,15px)/1 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;letter-spacing:.03em;white-space:nowrap;transform:rotate(var(--r,0deg)) scale(var(--s));transform-origin:center}.dy-sticker:nth-child(3n){color:#315d4b;background:#f3f5e9}.dy-sticker:nth-child(4n){color:#80571d;background:#fff1c9}.dy-sticker:nth-child(5n){border-radius:999px}.dy-load-card{position:relative;z-index:5;width:min(78vw,310px);aspect-ratio:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border:2px solid #eadcc8;border-radius:50%;background:rgba(255,253,248,.97);box-shadow:0 28px 90px -40px rgba(36,22,16,.65)}.dy-load-kicker{display:block;margin-bottom:14px;color:#241610;font:800 10px/1.2 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;letter-spacing:.32em;text-transform:uppercase}.dy-load-ring{position:relative;width:86px;height:86px;border-radius:50%}.dy-load-ring::before,.dy-load-ring::after{content:"";position:absolute;border-radius:50%}.dy-load-ring::before{inset:0;border:6px solid rgba(188,91,51,.16);border-top-color:#bc5b33;border-right-color:#f0b180;animation:dyRing 1s linear infinite}.dy-load-ring::after{inset:19px;background:#bc5b33;box-shadow:inset 0 0 0 6px #fff8ee}.dy-load-ring b{position:absolute;inset:0;z-index:2;display:grid;place-items:center;color:#fff8ee;font:700 18px/1 Georgia,"Times New Roman",serif}.dy-load-title{margin:17px 20px 8px;color:#241610;font:700 clamp(27px,7vw,38px)/1.05 Georgia,"Times New Roman",serif;letter-spacing:-.035em}.dy-load-copy{min-height:1.5em;margin:0 18px;color:#7a6a58;font:700 11px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;letter-spacing:.07em}
@keyframes dyLoaderFadeIn{from{opacity:0}to{opacity:1}}@keyframes dyRing{to{transform:rotate(360deg)}}@keyframes dyFieldDrift{0%,100%{transform:rotate(-3deg) scale(1.07) translateY(0)}50%{transform:rotate(-2deg) scale(1.07) translateY(-8px)}}
@media(max-width:640px){.dy-symbol-field{inset:-3%;grid-template-columns:repeat(7,1fr);grid-template-rows:repeat(16,1fr);gap:0;transform:rotate(-2deg) scale(1.03);animation-name:dyFieldDriftMobile}.dy-symbol-field span{min-width:28px;min-height:28px;font-size:24px;opacity:.21}.dy-sticker{--s:.62;padding:8px 10px}.dy-load-card{width:235px}.dy-load-title{font-size:28px;margin-top:13px}.dy-load-ring{width:70px;height:70px}.dy-load-ring::after{inset:15px}}
@keyframes dyFieldDriftMobile{0%,100%{transform:rotate(-2deg) scale(1.03) translateY(0)}50%{transform:rotate(-1deg) scale(1.03) translateY(-6px)}}
/* Compact high-density layout: more dated content remains visible per screen. */
html,body{max-width:100%;overflow-x:clip}.fk-home main,.fk-home #enhancedHome,.kd-sec,.kd-row,.kd-mqwrap{max-width:100%;min-width:0}.kd-row,.kd-mqwrap{overflow-x:auto;overscroll-behavior-inline:contain}.fk-home #Blog1 .blog-posts,.fk-home #blog-pager{display:none!important}
.fk-rest .blog-posts{grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.fk-rest .blog-posts .post{padding:18px}.fk-rest .blog-posts h3.post-title{font-size:21px}.fk-rest .blog-posts .post-snippet{font-size:13px;line-height:1.6;-webkit-line-clamp:3}.blog-posts .snippet-thumbnail-container{aspect-ratio:16/9}.dy-label-page #blog-pager{display:none!important}.dy-label-page .blog-posts{width:min(1180px,100%);margin-inline:auto;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:22px!important;padding:12px clamp(16px,4vw,46px) 28px!important}.dy-label-page .blog-posts .post{display:flex!important;min-width:0!important;min-height:430px;padding:0!important;overflow:hidden;border:1px solid var(--line);border-radius:18px;background:var(--surface);box-shadow:0 14px 38px -30px rgba(36,22,16,.55)}.dy-label-card{flex-direction:column}.dy-label-image{display:block;width:100%;aspect-ratio:16/9;overflow:hidden;background:linear-gradient(135deg,#ead8bc,#f8f0e3);color:var(--accent-dark)}.dy-label-image img{display:block;width:100%;height:100%;margin:0!important;padding:0!important;object-fit:cover;object-position:center}.dy-label-image span{display:grid;width:100%;height:100%;place-items:center;font:700 38px/1 var(--font-display)}.dy-label-card .post-title-container,.dy-label-card .post-header,.dy-label-card .post-body-container{padding-inline:20px}.dy-label-card .post-title-container{padding-top:19px}.dy-label-card .post-title{margin:0!important;font-size:22px!important;line-height:1.2!important}.dy-label-card .post-header{margin-top:12px}.dy-label-card .post-labels{display:flex;flex-wrap:wrap;gap:6px}.dy-label-card .post-labels a{margin:0!important}.dy-label-card .post-body-container{display:flex;flex:1;flex-direction:column;padding-bottom:20px}.dy-label-card .post-snippet{display:-webkit-box!important;margin:13px 0 17px!important;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:3}.dy-label-card .jump-link{margin-top:auto}.dy-label-status{grid-column:1/-1;min-height:86px;display:grid;place-items:center;padding:22px;color:var(--muted);font:800 10px/1.5 var(--font-body);letter-spacing:.13em;text-align:center;text-transform:uppercase}.dy-label-status:before{content:"";width:28px;height:28px;margin-bottom:9px;border:3px solid var(--line);border-top-color:var(--accent);border-radius:50%;animation:dyRing .85s linear infinite}.dy-label-status[data-finished='true']:before,.dy-label-status[data-error='true']:before{display:none}.dy-label-status[data-finished='true']{min-height:52px;opacity:.74}
/* Five tool benches share one compact row as one navigational unit. */
#kd-tools{padding-top:34px!important;padding-bottom:34px!important}#kd-tools .kd-head{margin-bottom:16px!important}#kd-tools .kd-digest{grid-template-columns:repeat(5,minmax(0,1fr))!important;gap:8px!important}#kd-tools .kd-dg{min-width:0;padding:12px 10px!important;border-radius:11px!important}#kd-tools .kd-dg b{font-size:14px!important}#kd-tools .kd-dg span{font-size:10px!important;line-height:1.4!important}#kd-tools .kd-dg i{font-size:8px!important}
/* Preserve the established brand header, moving rails and compact contact desk. */
.topbar-inner{height:clamp(92px,10vw,112px)!important}.topbar-title{gap:2px!important;padding:5px 0 13px!important;max-width:calc(100vw - 120px)}.topbar-title .tb-a{font:800 clamp(32px,4.7vw,50px)/.94 var(--font-display)!important;letter-spacing:.095em!important;white-space:nowrap}.topbar-title .tb-line{min-height:15px!important}.topbar-title .tb-b{font:500 clamp(10px,1.25vw,13px)/1.1 var(--font-body)!important;letter-spacing:.08em!important;color:var(--accent-dark)!important}.topbar-title .tb-caret{height:11px!important}.topbar-title .tb-squig{bottom:-8px!important;width:58px!important}
.kd-sec{width:100%;min-width:0;overflow:hidden}#kd-articles .kd-row{cursor:grab;scroll-snap-type:none;overscroll-behavior-inline:contain}#kd-articles .kd-row.kd-grabbing{cursor:grabbing;user-select:none}#kd-articles .kd-row[data-kd-auto='1']{scrollbar-width:none}#kd-articles .kd-row[data-kd-auto='1']::-webkit-scrollbar{display:none}
.kd-engage{position:relative;overflow:hidden!important;padding:clamp(30px,5vw,54px)!important;background:radial-gradient(480px 230px at 0 0,rgba(188,91,51,.12),transparent 65%),linear-gradient(145deg,#fffaf0,#f4e1c4)!important}.kd-engage::before{content:"?";position:absolute;right:-.04em;bottom:-.36em;color:rgba(156,69,34,.055);font:700 clamp(170px,27vw,330px)/1 var(--font-display);pointer-events:none}.kd-engage h2{font-size:clamp(32px,4.8vw,54px)!important;letter-spacing:-.035em}.kd-engage>p{max-width:760px!important;font-size:clamp(13px,1.5vw,16px)!important}.kd-eg-row{position:relative;display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px!important;max-width:760px;margin:25px auto 12px!important}.kd-eg{min-height:96px;padding:18px!important;border-radius:18px!important;display:flex!important;align-items:center;gap:15px;text-align:left;background:rgba(255,253,248,.92)!important;box-shadow:0 13px 32px -28px rgba(36,22,16,.75);font:inherit!important}.kd-eg-icon{width:52px;height:52px;flex:none;border-radius:15px;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent-dark)}.kd-eg-icon svg{display:block!important;width:26px!important;height:26px!important;stroke:currentColor!important;fill:none!important;stroke-width:1.65;stroke-linecap:round;stroke-linejoin:round}.kd-eg-copy{min-width:0}.kd-eg-copy strong{display:block;color:var(--ink);font:700 17px/1.2 var(--font-display)}.kd-eg-copy small{display:block;margin-top:6px;color:var(--muted);font:500 10px/1.45 var(--font-body);overflow-wrap:anywhere}.kd-eg-arrow{margin-left:auto;color:var(--accent-dark);font-size:22px;transition:transform .25s}.kd-eg:hover .kd-eg-arrow{transform:translateX(4px)}
@media(max-width:560px){.topbar-inner{height:88px!important}.topbar-title{max-width:calc(100vw - 104px)}.topbar-title .tb-a{font-size:27px!important;letter-spacing:.075em!important}.topbar-title .tb-b{font-size:10px!important}.kd-eg-row{grid-template-columns:1fr}.kd-eg{min-height:84px;padding:15px!important}.kd-eg-icon{width:46px;height:46px}.kd-engage{padding:30px 16px!important}}
@media(max-device-width:760px){.topbar-inner{height:88px!important}.topbar-title .tb-a{font-size:27px!important}.topbar-title .tb-b{font-size:10px!important}.kd-eg-row{grid-template-columns:1fr!important}}
@media(max-width:760px){.fk-rest .blog-posts,.fk-home .blog-posts{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:9px!important;padding:0 9px!important}.blog-posts .post{padding:11px!important}.blog-posts h3.post-title{font-size:15px!important}.blog-posts .post-header-line-1{font-size:8px!important}.blog-posts .post-labels a{padding:4px 7px!important;font-size:7px!important}.blog-posts .post-snippet{display:none!important}.dy-label-page .blog-posts{grid-template-columns:1fr!important;gap:16px!important;padding-inline:12px!important}.dy-label-page .blog-posts .post{min-height:440px!important}.dy-label-page .blog-posts .post-snippet{display:-webkit-box!important}.dy-label-card .post-title-container,.dy-label-card .post-header,.dy-label-card .post-body-container{padding-inline:18px}#kd-tools{padding:24px 8px!important}#kd-tools .kd-digest{grid-template-columns:repeat(5,minmax(0,1fr))!important;gap:4px!important}#kd-tools .kd-dg{padding:8px 4px!important;text-align:center}#kd-tools .kd-dg b{font-size:9px!important;line-height:1.15!important;overflow-wrap:anywhere}#kd-tools .kd-dg span,#kd-tools .kd-dg i{display:none!important}}
/* Keep below-fold modules out of initial layout/paint work where supported. */
.site-footer,.dy-site-faq,#sidebar_feed,.item-post .dy2>section,.item-post .dy2>figure{content-visibility:auto;contain-intrinsic-size:1px 720px}.dya-desk,.dy-auth-desk{content-visibility:auto;contain-intrinsic-size:1px 560px}
.item-post div.post-title{font:600 clamp(27px,2.9vw,40px)/1.14 var(--font-display);letter-spacing:-.02em;margin:0 0 18px;color:var(--ink);overflow-wrap:break-word}.dy-breadcrumb{display:flex;align-items:center;gap:8px;min-height:42px;padding:8px clamp(20px,4.5vw,48px);border-bottom:1px solid var(--line);color:var(--muted);font:600 11px/1.4 var(--font-body);letter-spacing:.06em}
.dy-breadcrumb a{color:var(--accent-dark);text-decoration:underline;text-underline-offset:3px}.dy-breadcrumb span:last-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dy-site-faq{padding:clamp(40px,6vw,80px) clamp(20px,4.5vw,48px);background:var(--surface);border-top:1px solid var(--line)}
.dy-site-faq h2{font-size:clamp(28px,4vw,48px);margin-bottom:20px}.dy-site-faq details{max-width:900px;border-top:1px solid var(--line);padding:15px 0}.dy-site-faq details:last-child{border-bottom:1px solid var(--line)}
.dy-site-faq summary{cursor:pointer;font-weight:700;list-style-position:inside}.dy-site-faq p{margin:10px 0 0;color:var(--muted)}
.dy-updated{display:inline-flex;margin:10px 0 4px;padding:6px 10px;border-radius:999px;background:var(--accent-soft);color:var(--accent-dark);font:700 10px/1.2 var(--font-body);letter-spacing:.06em;text-transform:uppercase}.dy-form-status{min-height:1.5em;margin:10px 0 0;font-size:13px;font-weight:600;color:var(--muted)}.dy-form-status[data-state='error']{color:#a32222}.dy-form-status[data-state='success']{color:#20733a}
.dy-privacy-lock,.dy-privacy-lock body{overflow:hidden!important}.dy-privacy-lock body::after{content:"";position:fixed;z-index:250;inset:0;background:rgba(248,240,227,.20);-webkit-backdrop-filter:blur(15px) saturate(.72);backdrop-filter:blur(15px) saturate(.72);pointer-events:auto}
.dy-privacy{position:fixed;z-index:260;left:50%;top:50%;width:min(620px,calc(100% - 30px));transform:translate(-50%,-50%);padding:clamp(30px,4vw,42px);background:rgba(255,248,239,.94);border:1px solid #d9b985;border-radius:28px;box-shadow:0 38px 120px rgba(56,31,15,.42);-webkit-backdrop-filter:blur(18px);backdrop-filter:blur(18px);display:none;overflow:hidden}.dy-privacy::before{content:"";position:absolute;inset:0;border-radius:inherit;background:linear-gradient(120deg,rgba(255,255,255,.68),transparent 48%);pointer-events:none}.dy-privacy>*{position:relative}
.dy-privacy.dy-open{display:block}.dy-privacy-close{position:absolute;z-index:2;right:16px;top:16px;width:42px;height:42px;display:grid;place-items:center;border:1px solid #dbc6aa;border-radius:50%;background:rgba(255,255,255,.78);color:#4e392b;font:500 25px/1 var(--font-body)}.dy-privacy-kicker{display:block;margin:0 52px 12px 0;color:#98502d;font:800 10px/1.4 var(--font-body);letter-spacing:.19em;text-transform:uppercase}.dy-privacy h2{font:700 clamp(32px,4.4vw,44px)/1.08 var(--font-display);margin:0 50px 14px 0}.dy-privacy p{font-size:15px;line-height:1.68;margin:0;color:#6c594c}.dy-privacy-actions{display:grid;gap:12px;margin-top:24px}.dy-privacy-actions button{display:flex;width:100%;min-height:54px;align-items:center;justify-content:center;padding:14px 18px;border:1px solid #d8c3a7;border-radius:14px;background:rgba(255,255,255,.12);color:#332319;font:800 13px/1.2 var(--font-body)}.dy-privacy-actions .dy-primary{min-height:68px;background:linear-gradient(135deg,#bd5a33,#9a4323);color:#fff;border-color:#9a4323;font-size:15px;box-shadow:0 14px 30px -14px #873718}.dy-privacy-actions button:not(.dy-primary){min-height:34px;padding:8px;background:transparent;border:0;border-radius:0;box-shadow:none;color:#5c493d}.dy-privacy-policy{display:block;margin-top:15px;color:#98502d;font:700 11px/1.4 var(--font-body);text-align:center;text-decoration:underline;text-underline-offset:3px}
.site-footer .ft-page-links .dy-privacy-manage{display:flex;width:100%;align-items:center;justify-content:space-between;gap:14px;min-height:46px;box-sizing:border-box;padding:10px 0;border:0;border-bottom:1px solid #b58e5d26;border-radius:0;background:transparent;color:#e8d7be;font:400 13px/1.6 var(--font-body,Inter,Arial,sans-serif);text-align:left;cursor:pointer}.site-footer .ft-page-links .dy-privacy-manage::after{content:'\2192';font-size:15px;color:#b58c5b;transition:transform .2s}.site-footer .ft-page-links .dy-privacy-manage:hover{color:#fff5e5;border-color:#c79860}.site-footer .ft-page-links .dy-privacy-manage:hover::after{transform:translateX(3px);color:#efbd7b}
.dy-password-wrap{position:relative}.dy-password-toggle{position:absolute;right:8px;top:50%;transform:translateY(-50%);padding:7px;border-radius:6px;font-size:12px;background:var(--surface);border:1px solid var(--line)}
@media print{.dy-privacy,.dy-privacy-manage,.dy-site-faq,.dy-breadcrumb,.dy-form-status{display:none!important}body{background:#fff!important;color:#000!important}.item-post .post-body,.page-body{font-size:11pt!important;line-height:1.5!important;color:#000!important}a[href]::after{content:" (" attr(href) ")";font-size:8pt;overflow-wrap:anywhere}}
@media(max-width:560px){.dy-privacy{width:calc(100% - 18px);padding:28px 20px 24px}.dy-privacy h2{font-size:31px;margin-right:36px}.dy-privacy p{font-size:13px}.dy-privacy-actions .dy-primary{min-height:62px}.dy-privacy-actions button{min-height:50px}.dy-privacy-close{right:10px;top:10px}.dy-breadcrumb{padding-right:58px}}
@media(prefers-reduced-motion:reduce){.dy-load-screen,.dy-load-screen *{animation:none!important;transition:none!important}}
/* DY_SITE_ENHANCEMENTS_CSS_END */

head.script:
//

/* KC-FULLWIDTH v2 : zero inline padding on transparent shell wrappers (depth 1-3), never on designed cards */
(function(){function shell(el){var c=getComputedStyle(el);if(!c)return false;
if(c.backgroundColor!=='rgba(0, 0, 0, 0)'||c.backgroundImage!=='none')return false;
return !(parseFloat(c.borderTopWidth)>0||parseFloat(c.borderRightWidth)>0||parseFloat(c.borderBottomWidth)>0||parseFloat(c.borderLeftWidth)>0);}
function sweep(root){if(!root)return;var lvl=[root],d=0;
while(d<3&&lvl.length){var nxt=[];for(var i=0;i<lvl.length;i++){var ch=lvl[i].children;for(var k=0;k<ch.length;k++){nxt.push(ch[k]);}}
for(var j=0;j<nxt.length;j++){var el=nxt[j];if(!el.style)continue;var known=el.matches&&el.matches('.pr-page,.wrap,.kpg,.knews,#articleHub,.tl,.principles,.who,#enhancedSite,.enh-original');if(known||shell(el)){el.style.setProperty('padding-left','0','important');el.style.setProperty('padding-right','0','important');}}
lvl=nxt;d++;}}
function run(){sweep(document.querySelector('.page-body'));sweep(document.querySelector('.post-body'));}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run);else run();
window.addEventListener('load',run);setTimeout(run,400);setTimeout(run,1200);})();


/* KC-TOKEN-GUARD v1 : decode any literal &#NNN; / &#xHH; token that Blogger's serve pipeline
 leaves in rendered text or JS-set attributes ? present pages, old installs, future pastes. */
(function(){var D=document;
function dec(s){if(!s||s.indexOf('&#')<0)return s;return s.replace(/&#(x[0-9a-fA-F]+|\d+);/g,function(m,g){
var c=(g.charAt(0)==='x'||g.charAt(0)==='X')?parseInt(g.slice(1),16):parseInt(g,10);
if(!isFinite(c)||c<32||c>0x10FFFF)return m;try{return String.fromCodePoint(c);}catch(e){return m;}});}
var SKIP={SCRIPT:1,STYLE:1,TEXTAREA:1,NOSCRIPT:1,TEMPLATE:1};
function fixText(n){if(!n||n.nodeType!==3)return;var p=n.parentElement;if(p&&SKIP[p.tagName])return;
var v=n.nodeValue;if(v&&v.indexOf('&#')>-1){var d=dec(v);if(d!==v)n.nodeValue=d;}}
function fixAttrs(el){if(!el||!el.attributes)return;for(var i=0;i<el.attributes.length;i++){var a=el.attributes[i];
if(a.value&&a.value.indexOf('&#')>-1){var d=dec(a.value);if(d!==a.value)el.setAttribute(a.name,d);}}}
function sweep(root){if(!root)return;fixText(root);
var tw=D.createTreeWalker(root,4,null);var list=[];while(tw.nextNode())list.push(tw.currentNode);
for(var i=0;i<list.length;i++)fixText(list[i]);
fixAttrs(root);var els=root.querySelectorAll?root.querySelectorAll('*'):[];
for(var k=0;k<els.length;k++)fixAttrs(els[k]);}
function run(){sweep(D.body);}
if(D.readyState==='loading')D.addEventListener('DOMContentLoaded',run);else run();
window.addEventListener('load',run);setTimeout(run,600);setTimeout(run,1800);setTimeout(run,4000);
if(window.MutationObserver){var mo=new MutationObserver(function(ms){for(var i=0;i<ms.length;i++){var m=ms[i];
if(m.type==='childList'){for(var j=0;j<m.addedNodes.length;j++){var n=m.addedNodes[j];
if(n.nodeType===3)fixText(n);else if(n.nodeType===1)sweep(n);}}
else if(m.type==='characterData')fixText(m.target);
else if(m.type==='attributes')fixAttrs(m.target);}});
var start=function(){if(D.body)mo.observe(D.body,{subtree:true,childList:true,characterData:true,attributes:true});};
if(D.body)start();else D.addEventListener('DOMContentLoaded',start);}})();
//

//
window.dataLayer=window.dataLayer||[];
window.gtag=window.gtag||function(){window.dataLayer.push(arguments);};
window.gtag('consent','default',{analytics_storage:'denied',ad_storage:'denied',ad_user_data:'denied',ad_personalization:'denied',wait_for_update:500});
/* Feed-only session cache. It cannot request Page, Post, label or archive documents. */
(function(){var memory={};function safe(url){try{var u=new URL(url,location.href);return u.origin===location.origin&&/^\/feeds\//.test(u.pathname);}catch(e){return false;}}function get(url,ttl){if(!safe(url))return Promise.reject(Error('document requests prohibited'));var key='dy-feed-cache:'+url,now=Date.now(),saved=null;try{saved=JSON.parse(sessionStorage.getItem(key)||'null');}catch(e){}if(saved&&now-saved.at<ttl)return Promise.resolve(saved.data);if(memory[url])return memory[url];memory[url]=fetch(url,{credentials:'same-origin'}).then(function(r){if(!r.ok)throw Error('feed');return r.json();}).then(function(data){try{sessionStorage.setItem(key,JSON.stringify({at:Date.now(),data:data}));}catch(e){}return data;}).then(function(data){delete memory[url];return data;},function(err){delete memory[url];throw err;});return memory[url];}var inlineIndex={"version":4,"generated_at":"2026-10-09T08:43:08Z","images":{"3923558914059133817":"https://upload.wikimedia.org/wikipedia/commons/a/a2/Vista_de_Madrid_-_Chamart%C3%ADn_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","4503926661552527887":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Hole_In_The_Earth_%28243171791%29.jpeg/1920px-Hole_In_The_Earth_%28243171791%29.jpeg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","3644713591392052280":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/City_of_London_Skyline_%2816114973978%29.jpg/1920px-City_of_London_Skyline_%2816114973978%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","1365618236906218504":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Marunouchi_skyline_%28dawn%29_%282083208284%29.jpg/1920px-Marunouchi_skyline_%28dawn%29_%282083208284%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","4054147490024048150":"https://upload.wikimedia.org/wikipedia/commons/7/74/Logo_Paris_La_D%C3%A9fense.png?ut