body.script:
//
//
(function(){
 var d = document, root = d.documentElement;

 /* Drawer sidebar */
 var dt = d.getElementById('drawerToggle'), sb = d.getElementById('sidebarBack'), sc = d.getElementById('scrim');
 function closeDrawer(){ root.classList.remove('drawer-open'); if (dt) dt.setAttribute('aria-expanded','false'); }
 if (dt) dt.addEventListener('click', function(){
 var open = root.classList.toggle('drawer-open');
 dt.setAttribute('aria-expanded', open ? 'true' : 'false');
 if (open) root.classList.remove('search-open');
 });
 if (sb) sb.addEventListener('click', closeDrawer);
 if (sc) sc.addEventListener('click', closeDrawer);

 /* Expanding search replaced by the full-screen KVSearch dialog */
 var st = d.getElementById('searchToggle');
 if (st) st.addEventListener('click', function(){
 root.classList.remove('drawer-open');
 if (window.KVSearch) window.KVSearch.open();
 });
 var stw = d.getElementById('search_top');
 if (stw) stw.addEventListener('click', function(e){ if (e.target === stw){ root.classList.remove('search-open'); if (st) st.setAttribute('aria-expanded','false'); } });
 /* Feed pagination : every "more posts" link serves 10 posts */
 try {
 [].slice.call(d.querySelectorAll('#blog-pager a, .blog-pager a')).forEach(function(a){
 var u = new URL(a.getAttribute('href'), location.origin);
 u.searchParams.set('max-results', '10');
 a.setAttribute('href', u.href);
 });
 } catch(e){}



 d.addEventListener('keydown', function(e){ if (e.key === 'Escape'){ closeDrawer(); root.classList.remove('search-open'); if (window.KVSearch) window.KVSearch.close(); } });
 /* Floating stack extras : share / whatsapp / toast */
 var toast = d.getElementById('fkToast'), toastT;
 function say(msg){ if (!toast) return; toast.textContent = msg; toast.classList.add('on');
 clearTimeout(toastT); toastT = setTimeout(function(){ toast.classList.remove('on'); }, 2200); }
 function pageUrl(){ return location.href.indexOf('dailyyield.blogspot.com') > -1 ? location.href : 'https://dailyyield.blogspot.com/'; }
 function pageTitle(){ return (d.title || 'Daily Yield').split('\u2014')[0].trim(); }
 var shB = d.getElementById('shareFab');
 if (shB) shB.addEventListener('click', function(){
 var url = pageUrl(), title = pageTitle();
 if (navigator.share){
 navigator.share({ title: title, url: url }).then(function(){ say('Shared \u2014 thank you'); }, function(){
 if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(url).then(function(){ say('Link copied'); }, function(){}); });
 } else if (navigator.clipboard && navigator.clipboard.writeText){
 navigator.clipboard.writeText(url).then(function(){ say('Link copied'); }, function(){ say('Could not copy'); });
 } else say('Copy the address bar link to share');
 });

 /* Share popups */
 d.querySelectorAll('.sharing').forEach(function(s){
 var btn = s.querySelector('.sharing-button');
 if (!btn) return;
 btn.addEventListener('click', function(e){
 e.stopPropagation();
 var was = s.classList.contains('open');
 d.querySelectorAll('.sharing.open').forEach(function(o){ o.classList.remove('open'); });
 s.classList.toggle('open', !was);
 btn.setAttribute('aria-expanded', !was ? 'true' : 'false');
 });
 });
 d.addEventListener('click', function(e){
 if (!e.target.closest('.sharing')) {
 d.querySelectorAll('.sharing.open').forEach(function(o){
 o.classList.remove('open');
 var b = o.querySelector('.sharing-button'); if (b) b.setAttribute('aria-expanded','false');
 });
 }
 });

 /* Copy link */
 d.querySelectorAll('.copy-link').forEach(function(b){
 b.addEventListener('click', function(e){
 e.stopPropagation();
 var url = b.getAttribute('data-url') || window.location.href;
 var done = function(){ var l = b.querySelector('.copy-label'); if (l){ l.textContent = 'Copied'; setTimeout(function(){ l.textContent = 'Copy link'; }, 1600); } };
 if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(url).then(done, done); else done();
 });
 });

 /* Scroll reveal with stagger */
 var els = Array.prototype.slice.call(d.querySelectorAll('.post-body .reveal, .page-body .reveal'));
 var reduce = root.className.indexOf('reduce') !== -1;
 var revealAll = function(){
 els.forEach(function(el){ el.classList.add('in'); el.classList.remove('will-reveal'); });
 };
 if ('IntersectionObserver' in window && !reduce) {
 var io = new IntersectionObserver(function(entries){
 entries.forEach(function(en){
 if (en.isIntersecting) {
 en.target.classList.add('in');
