function esc(s){return String(s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function hi(s,q){var t=esc(s);if(!q)return t;var i=t.toLowerCase().indexOf(q);if(i<0)return t;return t.slice(0,i)+'<mark>'+t.slice(i,i+q.length)+'</mark>'+t.slice(i+q.length);}
function thumbURL(th){if(!th)return '';return String(th).replace(/\/s\d+(-c)?\//,'/s400-c/').replace(/=s\d+(-c)?$/,'=s400-c').replace(/=s\d+(-c)?&/,'=s400-c&');}
function initials(s){var w=String(s).replace(/[^A-Za-z0-9 ]/g,' ').split(/\s+/).filter(Boolean);return ((w[0]||'F')[0]+((w[1]||'B')[0])).toUpperCase();}
function thumb(p,big){return '<span class="'+(big?'kvsd-thumb':'kvsd-rowthumb')+'"><i>'+initials(p.title)+'</i>'+(p.thumb?'<img alt="'+esc(p.title)+'" loading="lazy" src="'+esc(p.thumb)+'" onerror="this.remove()"/>':'')+'</span>';}
function strip(html){var tmp=d.createElement('div');tmp.innerHTML=html||'';return (tmp.textContent||'').replace(/\s+/g,' ');}
