function loadFeed(){
 if(state.posts||state.loading)return;state.loading=true;setStatus('Connecting to your blog feed\u2026');
 var got=[];
 function page(start){
 return fetch('/feeds/posts/default?alt=json&max-results=150&start-index='+start,{credentials:'omit'}).then(function(r){if(!r.ok)throw 0;return r.json();}).then(function(j){
 var en=(j&&j.feed&&j.feed.entry)||[];en.forEach(function(e){var labels=[];(e.category||[]).forEach(function(c){labels.push(c.term);});var link='';(e.link||[]).forEach(function(L){if(L.rel==='alternate')link=L.href;});got.push({title:(e.title&&e.title.$t)||'',link:link,date:new Date(e.published&&e.published.$t||Date.now()),labels:labels,text:strip(e.content&&e.content.$t),thumb:thumbURL(e.media$thumbnail&&e.media$thumbnail.url)});});
 var total=(j&&j.feed&&j.feed.openSearch$totalItems&&j.feed.openSearch$totalItems.$t)||got.length;
 if(got.length<Math.min(total,450)&&en.length)return page(start+150);return null;});}
 page(1).then(function(){state.loading=false;
 if(got.length){state.posts=got;state.live=true;setStatus('Live from your blog feed \u00b7 '+got.length+' posts',true);}
 else{state.posts=[];state.live=true;setStatus('Waiting for your first post \u2014 digest and headlines appear once you publish');}
 if(state.open)render();}).catch(function(){state.loading=false;state.posts=[];state.live=false;setStatus('Feed unreachable here \u2014 it connects on your live blog');if(state.open)render();});}
function isNews(p){return p.labels.some(function(l){return l==='News';});}
function digest(){var now=new Date(),today=dayKey(now),yest=dayKey(new Date(now.getTime()-86400000));
 return (state.posts||[]).filter(function(p){return !isNews(p);}).filter(function(p){var k=dayKey(p.date);return k===today||k===yest;}).sort(function(a,b){return b.date-a.date;});}
function headlines(){return (state.posts||[]).filter(isNews).sort(function(a,b){return b.date-a.date;}).slice(0,8);}
