 var items=digest();
 var dsig=items.map(function(p){return p.link+'|'+p.title;}).join(';');
 var dch=!(wrap.getAttribute('data-sig')===dsig&&wrap.children.length);wrap.setAttribute('data-sig',dsig);
 if(dch){
 if(!items.length){wrap.innerHTML='<p class="kvsd-empty">No articles published today or yesterday yet. The moment you publish, the newest writing scrolls here, right to left.</p>';}
 else{var cards=items.map(function(p,i){return '<a class="kvsd-mqcard" style="--i:'+i+'" href="'+esc(p.link)+'">'+thumb(p,true)+'<b>'+esc(fmtDate(p.date))+'</b><span>'+esc(p.title)+'</span><em>'+esc(p.labels.slice(0,2).join(' \u00b7 '))+'</em></a>';}).join('');
 wrap.innerHTML='<div class="kvsd-mq">'+cards+cards+'</div>';settleTrackHome(wrap.querySelector('.kvsd-mq'),cards);}
 }
 var nwrap=d.querySelector('.kvsd-mqwrap-news');var hn=headlines();
 var nsig=hn.map(function(p){return p.link+'|'+p.title;}).join(';');
 var nch=!(nwrap.getAttribute('data-sig')===nsig&&nwrap.children.length);nwrap.setAttribute('data-sig',nsig);
 if(nch){
 if(!hn.length){nwrap.innerHTML='<p class="kvsd-empty">No news dispatches yet. Publish a post with the News label and its headline scrolls here, newest first.</p>';}
 else{var nc=hn.map(function(p,i){return '<a class="kvsd-mqcard" style="--i:'+i+'" href="'+esc(p.link)+'">'+thumb(p,true)+'<b>'+esc(fmtDate(p.date))+'</b><span>'+esc(p.title)+'</span><em>'+esc(p.labels.slice(0,2).join(' \u00b7 '))+'</em></a>';}).join('');
 nwrap.innerHTML='<div class="kvsd-mq" id="kvsd-news">'+nc+nc+'</div>';settleTrackHome(nwrap.querySelector('.kvsd-mq'),nc);}
 }
 d.getElementById('kvsd-quick').innerHTML=QUICK.map(function(q,i){return (i?'<i>\u2022</i>':'')+'<a href="'+BASE+q.p+(q.a?'#'+q.a:'')+'">'+esc(q.n)+'</a>';}).join('');}
function toolMatches(q){var out=[];TOOLS.forEach(function(t){var n=t.n.toLowerCase(),k=(t.k||'').toLowerCase();var pos=n.indexOf(q);var score=-1;
 if(pos===0)score=100;else if(pos>0)score=70;else if(k.indexOf(q)>-1)score=40;
 if(score>-1)out.push({t:t,score:score});});
 return out.sort(function(a,b){return b.score-a.score;}).slice(0,8).map(function(x){return x.t;});}
function articleMatches(q){var out=[];(state.posts||[]).forEach(function(p){if(isNews(p))return;var hay=(p.title+' '+p.text).toLowerCase();var c=0,i=hay.indexOf(q);while(i>-1&&c<40){c++;i=hay.indexOf(q,i+q.length);}if(c>0)out.push({p:p,c:c});});
 return out.sort(function(a,b){return b.c-a.c||b.p.date-a.p.date;}).slice(0,8);}
function newsMatches(q){return (state.posts||[]).filter(function(p){return isNews(p)&&p.title.toLowerCase().indexOf(q)>-1;}).sort(function(a,b){return b.date-a.date;}).slice(0,8);}
function row(href,name,sub,tag,count,q,ph){return '<li style="--i:'+((row.i=(row.i||0)+1)-1)+'"><a href="'+esc(href)+'">'+(ph||'')+'<span class="kvsd-main"><span class="kvsd-name">'+hi(name,q)+'</span>'+(sub?'<span class="kvsd-sub">'+esc(sub)+'</span>':'')+'</span>'+(tag?'<span class="kvsd-tag">'+esc(tag)+'</span>':'')+(count?'<span class="kvsd-count">\u00d7'+count+'</span>':'')+'<span class="kvsd-arrow">\u2192</span></a></li>';}
function fillResults(q){row.i=0;
 var t=toolMatches(q),a=articleMatches(q),n=newsMatches(q);
 d.getElementById('kvsd-c1').textContent=t.length?t.length+' matched':'none';
 d.getElementById('kvsd-c2').textContent=a.length?'ranked by mentions':'none';
 d.getElementById('kvsd-c3').textContent=n.length?n.length+' matched':'none';
 d.getElementById('kvsd-r1').innerHTML=t.length?t.map(function(x){return row(BASE+x.p+(x.a?'#'+x.a:''),x.n,x.g,'tool','',q,'');}).join(''):'<li><p class="kvsd-none">No tool matches \u201c'+esc(q)+'\u201d \u2014 try SIP, EMI, SWP, gold, burn, valuation\u2026</p></li>';
 d.getElementById('kvsd-r2').innerHTML=a.length?a.map(function(x){return row(x.p.link,x.p.title,fmtDate(x.p.date)+' \u00b7 '+x.p.labels.slice(0,2).join(', '),'article',x.c,q,thumb(x.p,false));}).join(''):('<li><p class="kvsd-none">'+((state.posts||[]).length?'No article repeats \u201c'+esc(q)+'\u201d yet.':'No articles published yet \u2014 the tool links above are always live.')+'</p></li>');
 d.getElementById('kvsd-r3').innerHTML=n.length?n.map(function(x){return row(x.link,x.title,fmtDate(x.date),'news','',q,thumb(x.p||x,false));}).join(''):('<li><p class="kvsd-none">'+((state.posts||[]).length?'No news headline carries \u201c'+esc(q)+'\u201d yet.':'No news published yet \u2014 headlines appear the moment you publish.')+'</p></li>');
 var more=d.getElementById('kvsd-more');if(more)more.href=BASE+'/search?q='+encodeURIComponent(q);}
function render(){var q=state.q,def=d.getElementById('kvsd-default'),res=d.getElementById('kvsd-results');
 if(q.length<2){def.hidden=false;res.hidden=true;fillDefault();return;}
 def.hidden=true;res.hidden=false;fillResults(q);}
function focusables(){return [].slice.call(d.querySelectorAll('.kvsd-panel a[href],.kvsd-panel button,.kvsd-panel input')).filter(function(e){return e.offsetWidth||e.offsetHeight;});}
function open(){var dlg=d.getElementById('kvSearchDialog');if(!dlg||state.open)return;state.open=true;dlg.hidden=false;
