(function(){
var D=document,B='https://dailyyield.blogspot.com';
if(!D.body.classList.contains('fk-home')||D.getElementById('kdDesks')===null)return;
var rm=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
/* ---- marquee factory: constant px/s, seamless wrap, hover pause, lazy-capture drag ---- */
function marquee(wrapId,trackId,speed){
 var wrap=D.getElementById(wrapId),tr=D.getElementById(trackId);
 if(!wrap||!tr)return;
 var pos=0,hover=false,drag=null,last=0;
 function half(){return tr.scrollWidth/2;}
 function wp(p){var h=half();if(h<=0)return 0;p=p%h;if(p>0)p-=h;return p;}
 function paint(){tr.style.transform='translateX('+pos.toFixed(2)+'px)';}
 wrap.addEventListener('mouseenter',function(){hover=true;});
 wrap.addEventListener('mouseleave',function(){hover=false;});
 wrap.addEventListener('pointerdown',function(e){if(e.pointerType==='mouse'&&e.button!==0)return;drag={x:e.clientX,p:pos,id:e.pointerId,on:false};});
 wrap.addEventListener('pointermove',function(e){if(!drag)return;var dx=e.clientX-drag.x;
 if(!drag.on&&Math.abs(dx)>8){drag.on=true;wrap.classList.add('kd-grabbing');e.preventDefault();try{wrap.setPointerCapture(drag.id);}catch(_e){}}
 if(drag.on){pos=wp(drag.p+dx);paint();}});
 function end(){if(!drag)return;var on=drag.on;drag=null;wrap.classList.remove('kd-grabbing');if(on){wrap._sw=1;setTimeout(function(){wrap._sw=0;},700);}}
 wrap.addEventListener('pointerup',end);wrap.addEventListener('pointercancel',end);
 wrap.addEventListener('dragstart',function(e){e.preventDefault();});
 wrap.addEventListener('click',function(e){if(!wrap._sw)return;wrap._sw=0;var a=e.target.closest?e.target.closest('a'):null;if(a){e.preventDefault();e.stopPropagation();}},true);
 function frame(ts){if(!last)last=ts;var dt=Math.min(.05,(ts-last)/1000);last=ts;
 if(!drag&&!hover&&!rm&&tr.scrollWidth>wrap.clientWidth+40&&D.visibilityState==='visible'){pos=wp(pos-speed*dt);paint();}
 window.requestAnimationFrame(frame);}
 paint();window.requestAnimationFrame(frame);
}
/* duplicate desk tabs once for the seamless loop */
var dk=D.getElementById('kdDesks');
if(dk&&!dk.getAttribute('data-dup')){dk.setAttribute('data-dup','1');requestAnimationFrame(function(){var wr=D.getElementById('kdDeskWrap');if(wr&&dk.scrollWidth<=wr.clientWidth+8)return;var cp=dk.innerHTML;dk.insertAdjacentHTML('beforeend','<span aria-hidden="true" style="display:contents">'+cp+'</span>');});}
marquee('kdDeskWrap','kdDesks',42);
