function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function card(it){
 var a=D.createElement('a');a.className='kd-card';a.href=it.href;if(it.id)a.setAttribute('data-kd-entry',it.id);
 var th=D.createElement('div');th.className='kd-th';
 if(it.img){var im=D.createElement('img');im.src=it.img;if(it.fallback)im.setAttribute('data-dy-fallback',it.fallback);im.alt=it.title||'Daily Yield article preview';im.loading='lazy';th.appendChild(im);}
 else{th.textContent=it.letter||'\u2733';}
 var b=D.createElement('b');b.textContent=it.title;
 var i=D.createElement('i');i.textContent=it.meta;
 a.appendChild(th);a.appendChild(b);a.appendChild(i);return a;
}
function hydrate(items){var q=items.filter(function(it){return !it.img&&it.id;}).slice(),active=0;function pump(){while(active<4&&q.length){(function(it){active++;window.DYFeedCache.get('/feeds/posts/default/'+encodeURIComponent(it.id)+'?alt=json',300000).then(function(j){var e=j.entry||{},m=/<img[^>]+src=["']([^"']+)["']/.exec(e.content&&e.content.$t||''),img=m&&m[1]||'';if(!img)return;D.querySelectorAll('[data-kd-entry="'+it.id+'"] .kd-th').forEach(function(th){th.textContent='';var im=D.createElement('img');im.src=img;im.alt=it.title||'Daily Yield article preview';im.loading='lazy';im.decoding='async';th.appendChild(im);});}).catch(function(){}).then(function(){active--;pump();});})(q.shift());}}pump();}
function emptyBox(row,title,msg){
 row.innerHTML='';var e=D.createElement('div');e.className='kd-empty';
 var b=D.createElement('b');b.textContent=title;e.appendChild(b);
 e.appendChild(D.createTextNode(msg));row.appendChild(e);
}
function fill(row,items){
 row.innerHTML='';
 if(!items.length)return false;
 items.forEach(function(it){row.appendChild(card(it));});
 return true;
}
function autoRail(row,speed){
 if(!row||row.children.length<2)return;
 [].slice.call(row.querySelectorAll('[data-kd-clone]')).forEach(function(n){n.remove();});
 var originals=[].slice.call(row.children);
 originals.forEach(function(n){var c=n.cloneNode(true);c.setAttribute('data-kd-clone','1');c.setAttribute('aria-hidden','true');c.tabIndex=-1;row.appendChild(c);});
 row.setAttribute('data-kd-auto','1');
 requestAnimationFrame(function(){row._kdLoop=row.children[originals.length].offsetLeft-row.children[0].offsetLeft;});
 if(row._kdWired)return;row._kdWired=true;
 var pauseUntil=0,last=0;
 function pause(){pauseUntil=Date.now()+4500;}
 row.addEventListener('pointerdown',pause,{passive:true});row.addEventListener('touchstart',pause,{passive:true});row.addEventListener('wheel',pause,{passive:true});
 row.addEventListener('mouseenter',function(){pauseUntil=Infinity;});row.addEventListener('mouseleave',function(){pauseUntil=Date.now()+900;});
 function tick(ts){if(!last)last=ts;var dt=Math.min(.05,(ts-last)/1000);last=ts;
 if(!rm&&Date.now()>pauseUntil&&row._kdLoop>0&&D.visibilityState==='visible'){row.scrollLeft+=speed*dt;if(row.scrollLeft>=row._kdLoop)row.scrollLeft-=row._kdLoop;}
 requestAnimationFrame(tick);}
 requestAnimationFrame(tick);
}
function parse(json,needNews){
 var out=[],en=(json.feed&&json.feed.entry)||[];
 en.forEach(function(e){
 var cats=(e.category||[]).map(function(c){return c.term;});
 var isNews=cats.indexOf('News')!==-1;
 if(needNews?!isNews:isNews)return;
 var href='';(e.link||[]).forEach(function(l){if(l.rel==='alternate')href=l.href;});
 var img=e.media$thumbnail&&e.media$thumbnail.url||'';var m=/<img[^>]+src="([^"]+)"/.exec((e.summary&&e.summary.$t)||(e.content&&e.content.$t)||'');if(!img&&m)img=m[1];var pid=(e.id&&e.id.$t||'').split('post-').pop(),exact=(window.__dyImageIndex||{})[pid],fallback=(window.__dyImageFallbacks||{})[pid]||'';if(exact)img=exact;
 out.push({id:(e.id&&e.id.$t||'').split('post-').pop(),title:e.title&&e.title.$t||'Untitled',href:href,img:img,fallback:fallback,
 meta:(e.published&&e.published.$t||'').slice(0,10)+' \u00b7 '+(cats.filter(function(c){return c!=='News';})[0]||'General'),
 when:e.published&&e.published.$t||'',letter:(e.title&&e.title.$t||'\u2733').charAt(0).toUpperCase()});
 });
 out.sort(function(a,b){return a.when<b.when?1:-1;});
 return out;
}
var latest=D.getElementById('kdRowLatest'),pop=D.getElementById('kdRowPopular'),newsRow=D.getElementById('kdNewsRow');
emptyBox(latest,'Checking the shelves\u2026','Latest general articles will line up here the moment the feed answers.');
emptyBox(pop,'Checking the shelves\u2026','Reader favourites appear once the blog has published posts.');
emptyBox(newsRow,'Checking the wire\u2026','News dispatches will tick here once published.');
function articleInventory(){return Promise.all([window.DYFeedCache.get('/feeds/posts/summary/-/Kushal%20K.%20Daga?alt=json&max-results=16&orderby=published',300000),window.DYFeedCache.asset()]).then(function(parts){window.__dyImageIndex=parts[1].images||{};window.__dyImageFallbacks=parts[1].fallbacks||{};return parts[0];});}
function go(){
 articleInventory().then(function(j){
 var all=parse(j,false);
 var items=all.slice(0,8);
 if(!fill(latest,items))emptyBox(latest,'Waiting for your first post','This row fills with your latest general articles the moment you publish \u2014 no placeholders, no invented headlines.');
 else{autoRail(latest,31);hydrate(items);}
 var earlier=all.slice(8,16);
 if(fill(pop,earlier)){autoRail(pop,24);hydrate(earlier);}
 else emptyBox(pop,'More dated articles will appear here','This second row continues the same newest-first article timeline.');
 }).catch(function(){
 emptyBox(latest,'Feed unreachable here','On your live blog this row connects to the published article feed automatically.');
 emptyBox(pop,'Feed unreachable here','Popular picks connect on your live blog.');
 });
 Promise.all([window.DYFeedCache.get('/feeds/posts/summary/-/News?alt=json&max-results=15&orderby=published',300000),window.DYFeedCache.asset()]).then(function(parts){var j=parts[0];window.__dyImageIndex=parts[1].images||{};window.__dyImageFallbacks=parts[1].fallbacks||{};
 var items=parse(j,true).slice(0,12);
 var nsig=items.map(function(it){return it.title;}).join('|');
 if(items.length){
 if(nsig===window.__kdNewsSig&&newsRow.children.length)return;
 window.__kdNewsSig=nsig;
 newsRow.innerHTML='';
 var html=items.map(function(it){return '<a class="kd-card" href="'+esc(it.href)+'"><div class="kd-th">'+(it.img?'<img loading="lazy" alt="'+esc(it.title)+'" data-dy-fallback="'+esc(it.fallback||'')+'" src="'+esc(it.img)+'"/>':esc(it.letter))+'</div><b>'+esc(it.title)+'</b><i>'+esc(it.meta)+'</i></a>';}).join('');
 newsRow.innerHTML=html+html;
 marquee('kdNewsWrap','kdNewsRow',78);
 settleTrack(newsRow,html);
 } else emptyBox(newsRow,'Waiting for your first news post','Published posts labelled News will tick across this wire automatically.');
 }).catch(function(){emptyBox(newsRow,'Feed unreachable here','On your live blog the news wire connects to the published News feed.');});
}
go();
setInterval(function(){ if(!D.hidden) go(); },300000);
/* ---------- KC-HOME-V3: market pulse (60s) + home calculator bench ---------- */
(function(){
 var ptr = D.getElementById('khPTrack');
 function inr(v,dg){ try{ return '\u20b9' + v.toLocaleString('en-IN',{maximumFractionDigits:dg==null?0:dg}); }catch(e){ return '\u20b9' + Math.round(v); } }
 function chip(label, val, chg, unit){
 var c = D.createElement('span'); c.className = 'kh-pchip';
 var b = D.createElement('b'); b.textContent = label; c.appendChild(b);
 c.appendChild(D.createTextNode(val + (unit || '')));
 if (chg != null && isFinite(chg)){ var i = D.createElement('i'); i.className = chg >= 0 ? 'up' : 'dn'; i.textContent = (chg >= 0 ? '\u25b2' : '\u25bc') + Math.abs(chg).toFixed(2) + '%'; c.appendChild(i); }
 return c;
 }
 function pulse(){
 if (!ptr || D.hidden) return;
 fetch('https://scanner.tradingview.com/global/scan', { method:'POST', headers:{'Content-Type':'text/plain;charset=UTF-8'},
 body: JSON.stringify({ symbols:{ tickers:['NSE:NIFTY','BSE:SENSEX','TVC:GOLD','TVC:SILVER'] }, columns:['name','close','change','currency'] }) })
 .then(function(r){ return r.json(); }).then(function(j){
 if (!j || !j.data || !j.data.length) return;
 while (ptr.firstChild) ptr.removeChild(ptr.firstChild);
 j.data.forEach(function(row){
 var dd = row.d || [];
 var sym = row.s, close = dd[1], chg = dd[2], cur = (dd[3] || '').toLowerCase();
 var lab = sym.split(':')[1] || sym;
 var val, unit = '';
 if (sym === 'TVC:GOLD'){ val = inr(close * 0.321507 * (window.__khInr || 1), 0); unit = ' /10g'; }
 else if (sym === 'TVC:SILVER'){ val = inr(close * 32.1507 * (window.__khInr || 1) / 1000, 2) + 'k'; unit = ' /kg'; }
 else { val = Math.round(close).toLocaleString('en-IN'); unit = ''; }
 ptr.appendChild(chip(lab, val, chg, unit));
 });
 var fx = window.__khInr;
 if (fx) ptr.appendChild(chip('USD/INR', fx.toFixed(2), null, ''));
 }).catch(function(){});
 }
 fetch('https://open.er-api.com/v6/latest/USD').then(function(r){ return r.json(); }).then(function(j){
 if (j && j.rates && j.rates.INR){ window.__khInr = j.rates.INR; pulse(); }
 }).catch(function(){});
 pulse(); setInterval(pulse, 60000);
 function num(id){ var e = D.getElementById(id); return e ? parseFloat(e.value) || 0 : 0; }
 function calc(){
 var m = num('khSipM'), y = num('khSipY'), r = num('khSipR');
 var i = r / 12 / 100, n = y * 12;
 var fv = i > 0 ? m * ((Math.pow(1 + i, n) - 1) / i) * (1 + i) : m * n;
 var so = D.getElementById('khSipO'); if (so) so.textContent = inr(fv) + ' \u00b7 invested ' + inr(m * n);
 var P = num('khEmiP'), er = num('khEmiR') / 12 / 100, ny = num('khEmiY') * 12;
 var emi = er > 0 ? P * er * Math.pow(1 + er, ny) / (Math.pow(1 + er, ny) - 1) : P / ny;
 var eo = D.getElementById('khEmiO'); if (eo) eo.textContent = inr(emi) + ' /mo \u00b7 interest ' + inr(emi * ny - P);
 var L = num('khLuP'), ly = num('khLuY'), lr = num('khLuR') / 100;
 var lo = D.getElementById('khLuO'); if (lo) lo.textContent = inr(L * Math.pow(1 + lr, ly)) + ' \u00b7 from ' + inr(L);
 }
 ['khSipM','khSipY','khSipR','khEmiP','khEmiR','khEmiY','khLuP','khLuY','khLuR'].forEach(function(id){
 var e = D.getElementById(id); if (e) e.addEventListener('input', calc);
 });
 calc();
})();

